    15→ * 所有 SQL 执行一律走 executeSafeSql 安全执行层，路由层不直接拼 SQL。
    16→ */
    17→import { Router } from 'express';
    18→import { randomUUID } from 'node:crypto';
    19→import { ERROR_CODES } from '../infra/errorCodes';
