    43→import { retrieveBestFewShot } from '../utils/fewShotService';
    44→import { logger } from '../infra/logger';
    45→import { resolveStageTwoFailure } from '../utils/fallback/fallbackPipeline.js';
    46→
    47→const router = Router();
    48→
    49→// 3. 智能问数主端点（NL2SQL / 分析）：自然语言 → SQL → 真实执行 → 图表/解读
    50→router.post('/natural-language', rateLimiter, authMiddleware, requireRole('ADMIN', 'ANALYST'), async (req, res) => {
    51→  const startedAt = Date.now();
    52→  const user = req.user!;
    53→  const { schema, dataSourceId } = req.body;
    54→  const auditBase = {
    55→    userId: user.id,
    56→    username: user.username,
    57→    endpoint: 'query' as const,
    58→    dataSourceId: typeof dataSourceId === 'string' ? dataSourceId : '',
    59→  };
    60→
    61→  // L2 权限层：Service 侧复核（与路由 requireRole 构成 Controller+Service 双层校验）
    62→  if (user.role !== 'ADMIN' && user.role !== 'ANALYST') {
    63→    writeAudit({ ...auditBase, status: 'DENIED_AUTH', detail: `角色 ${user.role} 无问数权限`, durationMs: Date.now() - startedAt });
    64→    return res.status(403).json({ code: ERROR_CODES.FORBIDDEN, error: '当前角色没有智能问数权限' });
    65→  }
    66→
    67→  // P2-11 数据源访问控制：非 ADMIN 需命中部门/个人授权清单
    68→  if (auditBase.dataSourceId && !(await checkDataSourceAccess(user, auditBase.dataSourceId))) {
    69→    writeAudit({ ...auditBase, status: 'DENIED_AUTH', detail: '无数据源访问权限（ACL）', durationMs: Date.now() - startedAt });
    70→    return res.status(403).json({ code: ERROR_CODES.DS_ACCESS_DENIED, error: '没有该数据源的访问权限，可向管理员申请开通' });
    71→  }
    72→
    73→  // L1 输入层：控制字符过滤 + 注入特征拒绝 + 500 字截断
    74→  const clean = sanitizeQuestion(req.body.query);
    75→  if (clean.ok !== true) {
    76→    writeAudit({ ...auditBase, question: typeof req.body.query === 'string' ? req.body.query : '', status: 'DENIED_INPUT', detail: clean.reason, durationMs: Date.now() - startedAt });
    77→    return res.status(400).json({ code: ERROR_CODES.INVALID_INPUT, error: clean.reason });
    78→  }
    79→  const query = clean.question;
    80→
    81→  // 模型自选：请求指定引擎/模型时校验并在本请求上下文内切换（AsyncLocalStorage 传递，非法值直接拒绝）
    82→  const bodyModel = req.body.model && typeof req.body.model === 'object' ? req.body.model : {};
    83→  const modelSel = validateModelSelection(bodyModel.engine, bodyModel.model);
    84→  if (modelSel && 'error' in modelSel) {
    85→    writeAudit({ ...auditBase, question: query, status: 'DENIED_INPUT', detail: modelSel.error, durationMs: Date.now() - startedAt });
    86→    return res.status(400).json({ code: ERROR_CODES.INVALID_INPUT, error: modelSel.error });
    87→  }
    88→  if (modelSel && 'engine' in modelSel) setLlmOverride({ engine: modelSel.engine, model: modelSel.model });
    89→  const modelVariant = modelSel && 'engine' in modelSel ? `${modelSel.engine}:${modelSel.model}` : '';
    90→
    91→  // 金额单位自选（亿元/百万元/万元/元）：白名单外直接拒绝，避免非法值静默落入默认口径
    92→  const amountUnit = normalizeAmountUnit(req.body.amountUnit);
    93→  if (req.body.amountUnit != null && req.body.amountUnit !== '' && !amountUnit) {
    94→    writeAudit({ ...auditBase, question: query, status: 'DENIED_INPUT', detail: `非法金额单位：${String(req.body.amountUnit).slice(0, 20)}`, durationMs: Date.now() - startedAt });
    95→    return res.status(400).json({ code: ERROR_CODES.INVALID_INPUT, error: '金额单位仅支持：亿元、百万元、万元、元' });
    96→  }
    97→  // 单位进缓存键：显式选单位与不选（依赖知识库默认口径）分别缓存，防口径互串
    98→  const cacheVariant = [modelVariant, amountUnit || ''].filter(Boolean).join(':');
    99→
   100→  // L5 频率层：每用户 20 次/小时滑动窗口
   101→  const limit = await checkUserQueryLimit(user.id);
   102→  if (!limit.ok) {
   103→    writeAudit({ ...auditBase, question: query, status: 'DENIED_RATE', detail: limit.reason, durationMs: Date.now() - startedAt });
   104→    return res.status(429).json({ code: ERROR_CODES.RATE_LIMITED, error: limit.reason });
   105→  }
   106→
   107→  // L5 频率层：同用户并发限 1（昂贵的 LLM 调用串行化）；slotToken 绑定本次请求，释放时比对防误删
   108→  const slotToken = randomUUID();
   109→  if (!(await acquireQuerySlot(user.id, slotToken))) {
   110→    writeAudit({ ...auditBase, question: query, status: 'DENIED_RATE', detail: '存在进行中的查询', durationMs: Date.now() - startedAt });
   111→    return res.status(429).json({ code: ERROR_CODES.QUERY_IN_FLIGHT, error: '上一个查询仍在进行中，请等待完成后再试' });
   112→  }
   113→
   114→  // 客户端断开（前端 200s 超时 abort / 刷新页面 / 网络闪断）时立即释放并发槽，
   115→  // 让用户可以马上发起新查询；旧链路继续跑完，finally 里的释放因 token 已不匹配而为 no-op，
   116→  // 不会误删新请求的槽。正常结束时 writableEnded 为 true，不会重复释放。
   117→  res.on('close', () => {
   118→    if (!res.writableEnded) void releaseQuerySlot(user.id, slotToken);
   119→  });
   120→
   121→  // P2-7 SSE：客户端请求流式时，live 链路按阶段推送事件（早期校验错误仍返 JSON，前端按 Content-Type 区分）
   122→  const streamMode = req.body.stream === true;
   123→  // M1 推导留痕：每次问数生成唯一 traceId，全链路步骤旁路落库，响应携带供前端回放。
   124→  // P2-5：声明提前到 sseSend 之前（SSE 事件入重放缓冲以 traceId 为键，块作用域要求先声明）
   125→  const traceId = newTraceId();
   126→  let sseStarted = false;
   127→  const sseSend = (event: string, data: any) => {
   128→    if (!streamMode || res.writableEnded) return;
   129→    // P2-5 断线续传：事件先入重放缓冲（分配单调递增序号作为 SSE id），再写流。
   130→    // 客户端断开后 res.write 静默失败不阻断 LLM 链路，事件仍入缓冲，
   131→    // 客户端可凭 traceId + 已收序号经 GET /stream-replay 续传，不重新执行 SQL。
   132→    const payload = JSON.stringify(data);
   133→    const seq = appendQueryEvent(traceId, user.id, event, payload);
   134→    if (!sseStarted) {
   135→      res.writeHead(200, {
   136→        'Content-Type': 'text/event-stream; charset=utf-8',
   137→        'Cache-Control': 'no-cache',
   138→        Connection: 'keep-alive',
   139→        'X-Accel-Buffering': 'no',
   140→      });
   141→      sseStarted = true;
   142→    }
   143→    try {
   144→      res.write(`id: ${seq}\nevent: ${event}\ndata: ${payload}\n\n`);
   145→    } catch {
   146→      // 客户端已断开：事件已入重放缓冲，链路继续执行
   147→    }
   148→  };
   149→  const respond = (payload: any, event = 'done') => {
   150→    if (streamMode) {
   151→      sseSend(event, payload);
   152→      res.end();
   153→      return;
   154→    }
   155→    return res.json(payload);
   156→  };
   157→
   158→  // P2-10 生命周期钩子：进入/结束事件广播（审计、缓存与未来插件可挂接）
   159→  const hookCtx = {
   160→    userId: user.id,
   161→    username: user.username,
   162→    dataSourceId: typeof dataSourceId === 'string' ? dataSourceId : '',
   163→    question: query,
   164→    startedAt,
   165→    meta: { stream: streamMode, ...(modelVariant ? { model: modelVariant } : {}) },
   166→  };
   167→  emitBeforeQuery(hookCtx);
   168→
   169→  try {
   170→    // L3 上下文层：落库 schema + scope 白名单 + 敏感列过滤 + 5min 缓存（不信任前端提交的 schema）
   171→    // 必须在并发槽获取之后的同一 try 内执行：StateStore/DB 异常时 finally 才能保证释放槽，
   172→    // 否则一次抛错会把该用户的并发槽永久卡死（内存模式无 TTL 时只能重启恢复）
   173→    const ctx = await loadSchemaContext(dataSourceId, schema);
   174→
   175→    // 数据源级 AI 开关：数据源被停用（disconnected）后拒绝问数
   176→    if (ctx.status === 'disconnected') {
   177→      writeAudit({ ...auditBase, question: query, status: 'DENIED_SWITCH', detail: '数据源已停用智能问数', durationMs: Date.now() - startedAt });
   178→      return res.status(403).json({ code: ERROR_CODES.AI_SWITCHED_OFF, error: '该数据源的智能问数功能已被管理员停用' });
   179→    }
   180→
   181→    const effectiveSchema = ctx.schema;
   182→    const schemaGuidance = ctx.guidance;
   183→    const defense = { sensitiveFiltered: ctx.sensitiveRemoved.length, truncated: clean.truncated };
   184→
   185→    // L4 历史层：assistant 输出一律丢弃（防回流污染），user 消息逐条过注入检测，最多 5 轮
   186→    const sanitizedHistory: ChatMessage[] = sanitizeHistory(req.body.history);
   187→
   188→    // P0 双阶段真实执行：数据库型数据源 + 已落库文件数据源（v0.9.34）启用（LLM 生成 SQL → 安全执行 → 真实 rows 回喂分析）
   189→    const canRunLive = isLiveCapableType(ctx.dsType, ctx.fileBacked) && typeof dataSourceId === 'string' && dataSourceId.length > 0;
   190→    const traceMeta: TraceMeta = { userId: user.id, username: user.username, dataSourceId: typeof dataSourceId === 'string' ? dataSourceId : '', question: query };
   191→    if (canRunLive) {
   192→      // M2 计划模式：携带已批准 planId 时校验有效性（过期/越权/问题不匹配 → 409 提示重新制定）
   193→      let approvedPlan: QueryPlan | undefined;
   194→      const reqPlanId = typeof req.body.planId === 'string' ? req.body.planId : '';
   195→      if (reqPlanId) {
   196→        const consumed = await consumePlan(reqPlanId, user.id, dataSourceId);
   197→        if (consumed.ok !== true) {
   198→          writeAudit({ ...auditBase, question: query, status: 'DENIED_INPUT', detail: consumed.reason, durationMs: Date.now() - startedAt });
   199→          return res.status(409).json({ code: ERROR_CODES.PLAN_INVALID, error: consumed.reason });
   200→        }
   201→        if (consumed.plan.question !== query) {
   202→          writeAudit({ ...auditBase, question: query, status: 'DENIED_INPUT', detail: '提交问题与计划不匹配', durationMs: Date.now() - startedAt });
   203→          return res.status(409).json({ code: ERROR_CODES.PLAN_MISMATCH, error: '提交的问题与分析计划不匹配，请重新制定计划' });
   204→        }
   205→        approvedPlan = consumed.plan;
   206→      }
   207→
   208→      // P1-6 结果缓存：L1 归一化精确 + L2 embedding 语义（阈值默认 0.95，同域近似问题 0.85~0.95 区间误命中会答非所问，宁缺毋滥）；
   209→      // 缓存键含模型变体，避免跨模型串用；refreshCache=true 跳过缓存读（用户对缓存结果的强制刷新入口）
   210→      const ck = cacheKey(dataSourceId, query, cacheVariant);
   211→      const skipCacheRead = req.body.refreshCache === true;
   212→      const cached = skipCacheRead ? null : await getCachedQuery(ck);
   213→      if (cached) {
   214→        writeAudit({ ...auditBase, question: query, status: 'CACHE', executedSql: String(cached.executedSql || ''), rowCount: typeof cached.rowCount === 'number' ? cached.rowCount : -1, durationMs: Date.now() - startedAt });
   215→        emitAfterQuery(hookCtx, { status: 'CACHE', durationMs: Date.now() - startedAt });
   216→        // P2-12 DLP：缓存中为原始数据，响应出口按角色脱敏（ADMIN 豁免）
   217→        return respond(maskQueryPayload({ ...cached, fromCache: true, executionTimeMs: Date.now() - startedAt }, user));
   218→      }
   219→      // L2 语义缓存：同义改写问题复用最近成功结果，命中携带原问题供前端标注「来自相似问题缓存」
   220→      const semHit = skipCacheRead ? null : await getSemanticCachedQuery(dataSourceId, query, cacheVariant);
   221→      if (semHit) {
   222→        const similarity = Number(semHit.similarity.toFixed(4));
   223→        writeAudit({ ...auditBase, question: query, status: 'CACHE', detail: `L2 语义命中（相似度 ${similarity}）：${semHit.matchedQuestion.slice(0, 120)}`, executedSql: String(semHit.payload?.executedSql || ''), rowCount: typeof semHit.payload?.rowCount === 'number' ? semHit.payload.rowCount : -1, durationMs: Date.now() - startedAt });
   224→        emitAfterQuery(hookCtx, { status: 'CACHE', durationMs: Date.now() - startedAt });
   225→        return respond(maskQueryPayload({ ...semHit.payload, fromCache: true, semanticCache: { matchedQuestion: semHit.matchedQuestion, similarity }, executionTimeMs: Date.now() - startedAt }, user));
   226→      }
   227→
   228→      const live = await runLiveQuery({
   229→        query,
   230→        history: sanitizedHistory,
   231→        schema: effectiveSchema,
   232→        guidance: schemaGuidance,
   233→        dataSourceId,
   234→        dataSourceName: ctx.dataSourceName,
   235→        dsType: ctx.dsType || undefined,
   236→        sensitiveRemoved: ctx.sensitiveRemoved,
   237→        rowFilters: ctx.rowFilters,
   238→        allowIntrospection: ctx.allowIntrospection,
   239→        approvedPlan,
   240→        deepAnalysis: req.body.deepAnalysis === true,
   241→        amountUnit,
   242→        userId: user.id,
   243→        traceId,
   244→        // P2-5：stage 事件携带 traceId，前端收到首个阶段事件即可记录续传锚点
   245→        onStage: streamMode ? (stage, info) => sseSend('stage', { stage, traceId, ...(info || {}) }) : undefined,
   246→        // M1 推导留痕：旁路落库 + 流式模式下实时推送步骤详情（前端步骤器展示）
   247→        onTrace: (step) => {
   248→          void recordTraceStep(traceId, traceMeta, step);
   249→          if (streamMode) sseSend('trace', { traceId, ...step });
   250→        },
   251→      });
   252→      if (live.ok === 'clarify') {
   253→        // 歧义澄清：不执行 SQL，先把澄清问题与候选理解返回前端，由用户确认后重新提交
   254→        writeAudit({ ...auditBase, question: query, status: 'CLARIFY', detail: live.clarification.question.slice(0, 200), durationMs: Date.now() - startedAt });
   255→        emitAfterQuery(hookCtx, { status: 'CLARIFY', durationMs: Date.now() - startedAt });
   256→        return respond({
   257→          success: true,
   258→          executionTimeMs: Date.now() - startedAt,
   259→          needClarification: true,
   260→          clarification: live.clarification,
   261→          defense,
   262→          dataProvenance: 'live',
   263→          traceId,
   264→        }, 'clarify');
   265→      }
   266→      if (live.ok === 'refuse') {
   267→        // 拒答：问题与数据源无关/超出能力，如实反馈（不走演示数据托底）；小模型照抄模板句时兜底增强理由
   268→        const refuseReason = enrichRefusalReason(live.reason, effectiveSchema);
   269→        writeAudit({ ...auditBase, question: query, status: 'REFUSED', detail: refuseReason.slice(0, 200), durationMs: Date.now() - startedAt });
   270→        emitAfterQuery(hookCtx, { status: 'REFUSED', durationMs: Date.now() - startedAt });
   271→        recordConversation({ userId: user.id, username: user.username, dataSourceId, question: query, answerSummary: refuseReason.slice(0, 200), status: 'REFUSED', provenance: 'live', durationMs: Date.now() - startedAt }).catch((e: any) => logger.error('[Conversation] record failed:', e?.message || e));
   272→        return respond({
   273→          success: true,
   274→          executionTimeMs: Date.now() - startedAt,
   275→          refused: true,
   276→          refuseReason,
   277→          defense,
   278→          dataProvenance: 'live',
   279→          traceId,
   280→        }, 'refuse');
   281→      }
   282→      if (live.ok === true) {
   283→        const normalized = normalizeQueryResult(live.result);
   284→        if (normalized) {
   285→          writeAudit({ ...auditBase, question: query, status: 'SUCCESS', executedSql: live.executedSql, rowCount: live.rowCount, durationMs: Date.now() - startedAt });
   286→          emitAfterQuery(hookCtx, { status: 'SUCCESS', executedSql: live.executedSql, rowCount: live.rowCount, durationMs: Date.now() - startedAt });
   287→          const basePayload = { success: true, result: normalized, defense, dataProvenance: 'live' };
   288→          // L1 精确 + L2 语义索引一并写入（含原问题与 embedding，供同义改写命中）
   289→          await setCachedQuery(ck, { ...basePayload, executedSql: live.executedSql, rowCount: live.rowCount }, { dataSourceId, question: query, variant: cacheVariant });
   290→          // 对话历史服务端落库：成功问答 fire-and-forget 落库（历史面板 + 个人 few-shot 自学习），失败不阻断主链路
   291→          recordConversation({ userId: user.id, username: user.username, dataSourceId, question: query, executedSql: live.executedSql, answerSummary: String(normalized.aiExplanation || ''), status: 'SUCCESS', provenance: 'live', rowCount: live.rowCount, durationMs: Date.now() - startedAt }).catch((e: any) => logger.error('[Conversation] record failed:', e?.message || e));
   292→          // P2-12 DLP：缓存已写入原始数据（上方 setCachedQuery），响应出口按角色脱敏
   293→          return respond(maskQueryPayload({ ...basePayload, traceId, executionTimeMs: Date.now() - startedAt }, user));
   294→        }
   295→      }
   296→      // 真实执行链路失败：触发 Fallback 三层策略（rule_based → simpler_prompt → human_approval）
   297→      const failedSql = live.executedSql || 'unknown';
   298→      const fallbackStart = Date.now();
   299→      
   300→      try {
   301→        // Step 1: 调用 Fallback 调度器（v0.9.47 P0：schema 注入 + 三项依赖真实落库，三层策略全部接通）
   302→        const fallbackResult = await resolveStageTwoFailure(
   303→          query,
   304→          failedSql,
   305→          { 
   306→            dsId: dataSourceId, 
   307→            userId: String(user.id), // user.id is number, convert to string
   308→            schema: effectiveSchema,
   309→          },
   310→          {
   311→            logger,
   312→            // v0.9.47 P0：困难样本真实落库 adversarial_samples（表早已建好，此前为 console.log 占位）
   313→            persistHardNegative: async (sample) => {
   314→              const [result] = await getPool().query(
   315→                `INSERT INTO adversarial_samples (original_query, original_sql, error_message, data_source_id, user_id, username)
   316→                 VALUES (?, ?, ?, ?, ?, ?)`,
   317→                [sample.originalQuery.slice(0, 500), sample.originalSql.slice(0, 2000),
   318→                 (sample.errorMessage || '').slice(0, 500), sample.dataSourceId,
   319→                 parseInt(sample.userId, 10) || 0, user.username]
   320→              ) as any[];
   321→              return String((result as any).insertId ?? '');
   322→            },
   323→            // v0.9.47 P0：策略成功审计真实落库 fallback_audit_log
   324→            logFallbackAudit: async (_sql: string, params: any[]) => {
   325→              const [dsId, q, sql, strategy] = params;
   326→              await getPool().query(
   327→                `INSERT INTO fallback_audit_log (trace_id, query, failed_sql, used_strategy, latency_ms, success)
   328→                 VALUES (?, ?, ?, ?, ?, 1)`,
   329→                [traceId, String(q).slice(0, 500), String(sql).slice(0, 2000), String(strategy), Date.now() - fallbackStart]
