   500→// 3a-0. P2-5 SSE 断线续传（Last-Event-ID 语义）：重连按 traceId 回放已完成阶段，不重新执行 SQL。
   501→// 缓冲未命中（已过期 / 多实例部署落在无缓冲节点）返回 404，由前端降级为完整重试。
   502→router.get('/stream-replay/:traceId', authMiddleware, async (req, res) => {
   503→  const user = req.user!;
   504→  const traceId = String(req.params.traceId || '');
   505→  if (!/^tr_[A-Za-z0-9_]{6,40}$/.test(traceId)) {
   506→    return res.status(400).json({ code: ERROR_CODES.INVALID_INPUT, error: 'traceId 不合法' });
   507→  }
   508→  const owner = getTraceOwner(traceId);
   509→  if (owner === null) {
   510→    return res.status(404).json({ code: ERROR_CODES.NOT_FOUND, error: '流式会话不存在或已过期，请重新发起查询' });
   511→  }
   512→  if (owner !== user.id && user.role !== 'ADMIN') {
   513→    return res.status(403).json({ code: ERROR_CODES.FORBIDDEN, error: '无权续传他人的查询会话' });
   514→  }
   515→  // Last-Event-ID 头（SSE 标准语义）与 ?after= 查询参数双支持（fetch 重试无法自动带头）
   516→  const after = Math.max(0, Number(req.headers['last-event-id'] ?? req.query.after) || 0);
   517→
   518→  res.writeHead(200, {
   519→    'Content-Type': 'text/event-stream; charset=utf-8',
   520→    'Cache-Control': 'no-cache',
   521→    Connection: 'keep-alive',
   522→    'X-Accel-Buffering': 'no',
   523→  });
   524→  res.write(':ok\n\n');
   525→
   526→  let lastSent = after;
   527→  let ended = false;
   528→  const finish = (unsubscribe?: () => void, timer?: ReturnType<typeof setTimeout>) => {
   529→    if (ended) return;
   530→    ended = true;
   531→    unsubscribe?.();
   532→    if (timer) clearTimeout(timer);
   533→    try { res.end(); } catch { /* 已断开 */ }
   534→  };
   535→  // 返回 true 表示写入的是终态事件；seq 去重保证回放/订阅竞态下不重不漏
   536→  const writeEvent = (e: BufferedSseEvent): boolean => {
   537→    if (e.seq <= lastSent) return isTerminalEvent(e.event);
   538→    lastSent = e.seq;
   539→    try {
   540→      res.write(`id: ${e.seq}\nevent: ${e.event}\ndata: ${e.data}\n\n`);
   541→    } catch {
   542→      // 客户端再次断开：由 req close 监听统一清理
   543→    }
   544→    return isTerminalEvent(e.event);
   545→  };
   546→
   547→  // 先回放存量（断线期间已完成的事件即时补齐）
   548→  for (const e of getEventsAfter(traceId, after)?.events ?? []) writeEvent(e);
   549→  if (isTerminal(traceId)) { finish(); return; }
   550→
   551→  // 未终态：订阅增量推送，直到终态到达或 5 分钟兜底超时
   552→  const timer = setTimeout(() => finish(unsubscribe), 5 * 60 * 1000);
   553→  timer.unref?.();
   554→  const unsubscribe = subscribeTrace(traceId, (e) => {
   555→    if (writeEvent(e)) finish(unsubscribe, timer);
   556→  });
   557→  // 订阅挂上后补一次漏（回放与订阅之间可能到达的新事件）
   558→  for (const e of getEventsAfter(traceId, lastSent)?.events ?? []) writeEvent(e);
   559→  if (isTerminal(traceId)) { finish(unsubscribe, timer); return; }
   560→  req.on('close', () => finish(unsubscribe, timer));
   561→});
