     1→/**
     2→ * L5 频率层：智能问数用户级配额（架构图约定：20 次/小时 + 同用户并发限 1）。
     3→ * 与 IP 级 rateLimiter 互补：IP 限流防匿名爆破，本模块按登录用户约束昂贵的 LLM 调用。
     4→ * P0-2：默认进程内存（滑动窗口语义不变）；配置 REDIS_URL 后走 Redis（固定小时窗口
     5→ * INCR + 分布式锁并发槽），多实例共享且进程崩溃后槽位可自动过期释放。
     6→ */
     7→import { getStateStore, isRedisEnabled } from './stateStore';
     8→
     9→const WINDOW_MS = 60 * 60 * 1000; // 1 小时滑动窗口
    10→const maxPerWindow = () => Number(process.env.USER_QUERY_RATE_MAX) || 20;
    11→/** Redis 并发槽 TTL：覆盖最长问数链路耗时，崩溃后自动释放避免永久锁死（内存模式同样以此兜底） */
    12→export const SLOT_TTL_SEC = 15 * 60;
    13→
    14→const hits = new Map<number, number[]>(); // userId -> 窗口内时间戳
    15→/** 进行中的查询（并发互斥）：token 绑定请求，exp 为兜底过期时间（对齐 Redis 模式 TTL 语义） */
    16→const inflight = new Map<number, { token: string; exp: number }>();
    17→
    18→export interface RateCheck {
    19→  ok: boolean;
    20→  reason?: string;
    21→}
    22→
    23→/** 频率检查：窗口内已满则拒绝，通过则立即计数。Redis 模式为固定小时窗口（拒绝也计数，语义略保守）。 */
    24→export async function checkUserQueryLimit(userId: number, now: number = Date.now()): Promise<RateCheck> {
    25→  if (isRedisEnabled()) {
    26→    const bucket = Math.floor(now / WINDOW_MS);
    27→    try {
    28→      const n = await getStateStore().incrWindow(`uql:${userId}:${bucket}`, Math.ceil(WINDOW_MS / 1000) + 100);
    29→      if (n > maxPerWindow()) {
    30→        const retryMin = Math.max(1, Math.ceil(((bucket + 1) * WINDOW_MS - now) / 60000));
    31→        return { ok: false, reason: `已达到每小时 ${maxPerWindow()} 次的问数上限，请约 ${retryMin} 分钟后再试` };
    32→      }
    33→      return { ok: true };
    34→    } catch {
    35→      // fail-closed：配额状态不可信时拒绝（避免 Redis 故障期 LLM 调用失控）
    36→      return { ok: false, reason: '服务暂时不可用（配额存储异常），请稍后重试' };
    37→    }
    38→  }
    39→  const windowStart = now - WINDOW_MS;
    40→  const list = (hits.get(userId) || []).filter((t) => t > windowStart);
    41→  if (list.length >= maxPerWindow()) {
    42→    const retryAfterSec = Math.ceil((list[0] + WINDOW_MS - now) / 1000);
    43→    return { ok: false, reason: `已达到每小时 ${maxPerWindow()} 次的问数上限，请约 ${Math.ceil(retryAfterSec / 60)} 分钟后再试` };
    44→  }
    45→  list.push(now);
    46→  hits.set(userId, list);
    47→  return { ok: true };
    48→}
    49→
    50→/**
    51→ * 并发互斥：同一用户同一时间仅允许一个进行中的查询。
    52→ * Redis 模式为分布式锁（token 绑定请求，释放时比对防误删）；返回 false 表示已有在途查询。
    53→ * 内存模式同样记录 token 与过期时间：客户端断开可提前释放（见路由 res.on('close')），
    54→ * 旧链路跑完后的 finally 释放因 token 不匹配为 no-op，不会误删新请求的槽。
    55→ */
    56→export async function acquireQuerySlot(userId: number, token = 'local', now: number = Date.now()): Promise<boolean> {
    57→  if (isRedisEnabled()) {
    58→    try {
    59→      return await getStateStore().acquireLock(`uqs:${userId}`, token, SLOT_TTL_SEC);
    60→    } catch {
    61→      return false; // fail-closed
    62→    }
    63→  }
    64→  const cur = inflight.get(userId);
    65→  if (cur && cur.exp > now) return false;
    66→  inflight.set(userId, { token, exp: now + SLOT_TTL_SEC * 1000 });
    67→  return true;
    68→}
    69→
    70→export async function releaseQuerySlot(userId: number, token = 'local'): Promise<void> {
    71→  if (isRedisEnabled()) {
    72→    try {
    73→      await getStateStore().releaseLock(`uqs:${userId}`, token);
    74→    } catch {
    75→      // 释放失败由 TTL 过期兜底
    76→    }
    77→    return;
    78→  }
    79→  const cur = inflight.get(userId);
    80→  if (cur && cur.token === token) inflight.delete(userId);
    81→}
    82→
    83→// 定期清理过期窗口记录
    84→setInterval(() => {
    85→  const windowStart = Date.now() - WINDOW_MS;
    86→  for (const [key, list] of hits.entries()) {
    87→    const fresh = list.filter((t) => t > windowStart);
    88→    if (fresh.length === 0) hits.delete(key);
    89→    else hits.set(key, fresh);
    90→  }
    91→}, WINDOW_MS).unref();
    92→
    93→/** 仅供单元测试使用 */
    94→export function _resetForTest(): void {
    95→  hits.clear();
    96→  inflight.clear();
    97→}
