     1→/**
     2→ * P2-11 数据源访问控制（ACL）模块：组织/部门维度授权。
     3→ *
     4→ * 模型：data_sources.acl_json = { departments: string[], userIds: number[] }
     5→ * - NULL 或两组皆空 → 不限制（全员可见，保持存量行为）
     6→ * - 非空 → 仅 ADMIN / 清单内部门成员 / 清单内个人用户可访问
     7→ * 与 DataScope（表/列/行级圈定）正交：ACL 决定「能否看到/使用该数据源」，scope 决定「可用哪些表列」。
     8→ */
     9→import type { AuthUser } from './auth';
    10→import { getPool } from '../infra/db';
    11→import type { RowDataPacket } from 'mysql2';
    12→
    13→export interface DataSourceAcl {
    14→  departments: string[];
    15→  userIds: number[];
    16→}
    17→
    18→/** 解析 acl_json 原始值（string/object/null 均可）；两组皆空时归一为 null（=不限制） */
    19→export function parseAcl(raw: unknown): DataSourceAcl | null {
    20→  if (raw === null || raw === undefined) return null;
    21→  let obj: any = raw;
    22→  if (typeof raw === 'string') {
    23→    if (!raw.trim()) return null;
    24→    try {
    25→      obj = JSON.parse(raw);
    26→    } catch {
    27→      return null;
    28→    }
    29→  }
    30→  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return null;
    31→  const departments: string[] = Array.isArray(obj.departments)
    32→    ? obj.departments
    33→        .filter((d: unknown): d is string => typeof d === 'string' && d.trim().length > 0)
    34→        .map((d: string) => d.trim())
    35→    : [];
    36→  const userIds: number[] = Array.isArray(obj.userIds)
    37→    ? obj.userIds.map((n: unknown) => Number(n)).filter((n: number) => Number.isInteger(n) && n > 0)
    38→    : [];
    39→  if (departments.length === 0 && userIds.length === 0) return null;
    40→  return { departments, userIds };
    41→}
    42→
    43→/** 纯函数判定：用户是否可访问某 ACL 的数据源 */
    44→export function canAccessDataSource(
    45→  user: Pick<AuthUser, 'id' | 'role' | 'department'> | null | undefined,
    46→  acl: DataSourceAcl | null
    47→): boolean {
    48→  if (!user) return false;
    49→  if (user.role === 'ADMIN') return true;
    50→  if (!acl) return true; // 未配置 = 不限制
    51→  if (acl.userIds.includes(user.id)) return true;
    52→  const dept = String(user.department || '').trim();
    53→  if (dept && acl.departments.includes(dept)) return true;
    54→  return false;
    55→}
    56→
    57→/** 加载指定数据源的 ACL（数据源不存在时返回 null，由调用方按既有"不存在"链路处理） */
    58→export async function loadDataSourceAcl(dataSourceId: string): Promise<DataSourceAcl | null> {
    59→  const [rows] = await getPool().query<RowDataPacket[]>('SELECT acl_json FROM data_sources WHERE id = ? LIMIT 1', [dataSourceId]);
    60→  const row = rows[0];
    61→  if (!row) return null;
    62→  return parseAcl(row.acl_json);
    63→}
    64→
    65→/** 服务端访问校验入口：问数/执行/报表等链路在鉴权后调用 */
    66→export async function checkDataSourceAccess(
    67→  user: Pick<AuthUser, 'id' | 'role' | 'department'>,
    68→  dataSourceId: string
    69→): Promise<boolean> {
    70→  if (user.role === 'ADMIN') return true;
    71→  const acl = await loadDataSourceAcl(dataSourceId);
    72→  return canAccessDataSource(user, acl);
    73→}
    74→
    75→/**
    76→ * 审批通过时并入个人授权：将 userId 加入 acl_json.userIds（保留既有部门清单）。
    77→ * 注意：审批是低频管理操作，先读后写无事务保护可接受；重复并入幂等。
    78→ */
    79→export async function grantUserAccess(dataSourceId: string, userId: number): Promise<void> {
    80→  const [rows] = await getPool().query<RowDataPacket[]>('SELECT acl_json FROM data_sources WHERE id = ? LIMIT 1', [dataSourceId]);
    81→  const row = rows[0];
    82→  if (!row) throw new Error('数据源不存在');
    83→  const acl = parseAcl(row.acl_json) || { departments: [], userIds: [] };
    84→  if (!acl.userIds.includes(userId)) acl.userIds.push(userId);
    85→  await getPool().query('UPDATE data_sources SET acl_json = ? WHERE id = ?', [JSON.stringify(acl), dataSourceId]);
    86→}
    87→
    88→/** PUT /:id/acl 入参清洗：白名单结构 + 长度上限；返回可入库的规范结构（空 → null 解除限制） */
    89→export function sanitizeAcl(body: unknown): DataSourceAcl | null {
    90→  if (!body || typeof body !== 'object') return null;
    91→  const raw = body as Record<string, unknown>;
    92→  const departments: string[] = Array.isArray(raw.departments)
    93→    ? Array.from(
    94→        new Set(
    95→          raw.departments
    96→            .filter((d): d is string => typeof d === 'string')
    97→            .map((d) => d.trim().slice(0, 100))
    98→            .filter((d) => d.length > 0)
    99→        )
   100→      ).slice(0, 50)
   101→    : [];
   102→  const userIds: number[] = Array.isArray(raw.userIds)
   103→    ? Array.from(new Set(raw.userIds.map((n) => Number(n)).filter((n) => Number.isInteger(n) && n > 0))).slice(0, 200)
   104→    : [];
   105→  if (departments.length === 0 && userIds.length === 0) return null;
   106→  return { departments, userIds };
   107→}
   108→

