    36→  if (dsType === 'greenplum') return { label: 'Greenplum（PostgreSQL 兼容方言）', rules: '- 方言要点：分页仅支持 LIMIT n OFFSET m；标识符用双引号；日期用 EXTRACT/date_trunc；空值用 COALESCE；字符串拼接用 ||；分组聚合用 STRING_AGG' };
