   131→        if (depth === 0) {
   132→          // CTE 定义闭合：后续是 `, name AS (` 则还有下一段 CTE，否则链结束
   133→          const nextCte = sql.slice(i + 1).match(/^\s*,\s*[`"\w]+\s+as\s*\(/i);
   134→          if (nextCte) {
   135→            // 让 for 的 i++ 恰好落在下一个 CTE 的左括号上（depth++ 不错漏）
   136→            i += nextCte[0].length - 1;
   137→            continue;
   138→          }
   139→          chainEnd = i;
   140→          break;
   141→        }
   142→      }
   143→    }
   144→    if (chainEnd >= 0) {
   145→      const tail = sql.slice(chainEnd + 1);
   146→      if (/^\s*select\b/i.test(tail)) {
   147→        return sql.slice(0, chainEnd + 1) + tail.replace(/^(\s*)select\b/i, `$1SELECT /*+ MAX_EXECUTION_TIME(${ms}) */`);
   148→      }
   149→    }
   150→    return sql;
   151→  }
   152→  return sql.replace(/^\s*select\b/i, `SELECT /*+ MAX_EXECUTION_TIME(${ms}) */`);
   153→}
   154→
   155→// 写/DDL/管理类关键字一律拒绝（对剥离注释与字符串后的 SQL 做整词匹配）。
   156→// 注意词表必须避开合法 SELECT 语法内会出现的词：desc（ORDER BY DESC）、replace/use/set/do/call/check/load/show
   157→// 等不在此列——这些语句本就无法出现在 SELECT 内部，"只允许 SELECT 开头"一层已拦截。
   158→// procedure 在列：PROCEDURE ANALYSE 是 SELECT 内真实存在的危险构造。
   159→const FORBIDDEN_PATTERN =
   160→  /\b(insert|update|delete|drop|alter|truncate|create|grant|revoke|rename|lock|unlock|exec|execute|outfile|infile|dumpfile|procedure|explain|handler|install|uninstall|kill|shutdown|analyze|optimize|repair|checksum|flush|reset|purge|binlog|prepare|deallocate|release|savepoint|rollback|commit|begin|xa)\b/i;
   161→
   162→/** M3 应用库中间表查询校验复用同一危险关键字词表 */
   163→export const FORBIDDEN_KEYWORD_RE = FORBIDDEN_PATTERN;
   164→
   165→// 注意：项目 tsconfig 未开启 strictNullChecks，真值窄化（if (!x.ok)）对判别联合不生效，
   166→// 所有使用处必须用 x.ok !== true / x.ok === false 的显式比较（同 queryGuard 的先例）。
   167→export type SqlSafetyResult = { ok: true; sql: string; astFallback?: boolean } | { ok: false; reason: string };
   168→
   169→/**
   170→ * 剥离单行/块注释与字符串字面量，避免注释或字符串中的关键字干扰结构校验。
   171→ * dialect='pg' 时保留双引号段：PostgreSQL/Greenplum 双引号是标识符（表名/列名），
   172→ * 若当字符串字面量剥掉，表引用提取会丢失 FROM 目标，导致合法 PG SQL 被误拦（v0.9.1 修复）。
   173→ */
   174→export function stripCommentsAndStrings(sql: string, dialect: SqlDialect = 'mysql'): string {
   175→  const out = sql
   176→    .replace(/\/\*[\s\S]*?\*\//g, ' ')
   177→    .replace(/--[^\n]*/g, ' ')
   178→    .replace(/#[^\n]*/g, ' ')
   179→    .replace(/'(?:[^'\\]|\\.|'')*'/g, "''");
   180→  // MySQL 默认模式下双引号等同字符串字面量（非 ANSI_QUOTES），剥掉防关键字干扰
   181→  return dialect === 'pg' ? out : out.replace(/"(?:[^"\\]|\\.)*"/g, '""');
   182→}
   183→
   184→function cleanIdent(raw: string): string {
   185→  const stripped = raw.replace(/[`"]/g, '');
   186→  const parts = stripped.split('.');
   187→  return (parts[parts.length - 1] || '').trim().toLowerCase();
   188→}
   189→
   190→/**
   191→ * 提取 SQL 中 FROM/JOIN 引用的全部表名（含子查询，支持反引号与库名前缀、逗号分隔多表）。
   192→ * 返回小写表名清单（不含库名前缀）。
   193→ */
   194→export function extractTableRefs(strippedSql: string): string[] {
   195→  const refs = new Set<string>();
   196→  const KEYWORDS = /^(select|where|on|using|left|right|inner|outer|cross|natural|straight_join|as|join|full)$/i;
   197→
   198→  // 主扫描：逐个命中 FROM/JOIN 后紧跟的标识符（全局扫描天然覆盖子查询内部的 FROM）
   199→  const direct = /\b(?:from|join)\s+([`"\w.]+)/gi;
   200→  let m: RegExpExecArray | null;
   201→  while ((m = direct.exec(strippedSql))) {
   202→    if (!KEYWORDS.test(m[1])) refs.add(cleanIdent(m[1]));
   203→  }
   204→  // 补充：FROM 子句内逗号分隔的多表（JOIN 链已由主扫描覆盖；到子句终止或右括号为止）
   205→  const fromSeg = /\bfrom\b([\s\S]*?)(?=\bwhere\b|\bgroup\s+by\b|\border\s+by\b|\blimit\b|\bhaving\b|\bunion\b|\)|;|$)/gi;
   206→  while ((m = fromSeg.exec(strippedSql))) {
   207→    // 段内含括号（子查询/函数）时逗号分表不可靠：子查询 SELECT 列表的逗号会把列名/聚合函数名
   208→    // （如 SUM/BNTFJE）误当表名拒拦合法 SQL；子查询内部真实表已由主扫描 FROM/JOIN 命中覆盖
   209→    if (/[()]/.test(m[1])) continue;
   210→    for (const slotRaw of m[1].split(',')) {
   211→      const slot = slotRaw.split(/\bon\b|\busing\b/i)[0];
   212→      const lead = slot.trimStart().match(/^([`"\w.]+)/);
   213→      if (!lead || KEYWORDS.test(lead[1])) continue; // 子查询 (SELECT...) 由主扫描覆盖其内部表
   214→      refs.add(cleanIdent(lead[1]));
   215→    }
   216→  }
   217→  refs.delete('');
   218→  return [...refs];
   219→}
   220→
   221→/**
   222→ * v0.4.15 复杂 SQL（CTE 放行）：提取 WITH 链定义的 CTE 名集合（入参为剥离字符串后的 SQL）。
   223→ * CTE 名是查询内临时结果集别名而非真实表，表名白名单与 AST 复核均须排除，否则合法 CTE 被误拦。
   224→ * 仅 WITH 开头时有值；`name AS (` 结构不会出现在 SELECT 列列表（别名后不跟左括号），正则安全。
   225→ */
   226→export function extractCteNames(strippedSql: string): Set<string> {
   227→  const names = new Set<string>();
   228→  if (!/^\s*with\b/i.test(strippedSql)) return names;
   229→  const re = /(?:\bwith|,)\s*([`"\w]+)\s+as\s*\(/gi;
   230→  let m: RegExpExecArray | null;
   231→  while ((m = re.exec(strippedSql))) {
   232→    names.add(m[1].replace(/[`"]/g, '').toLowerCase());
   233→  }
   234→  return names;
   235→}
   236→
   237→// P1 AST 二道防线：node-sql-parser 语法树级复核。
   238→// 解析成功 → 强校验（所有语句类型必须为 select、AST 提取的表必须全在白名单）；
   239→// 解析失败 → 放行不误伤（MySQL 方言边界），此时第一道正则防线的结论已生效。
   240→// v0.4.15：cteNames 为 WITH 链定义的 CTE 名（临时结果集别名），tableList 会将其误报为表，须排除。
   241→const astParser = new SqlAstParser();
   242→export function checkAstSafety(
   243→  sql: string,
   244→  allowedTables: Set<string>,
   245→  dialect: SqlDialect = 'mysql',
   246→  cteNames: Set<string> = new Set()
   247→): { ok: true; astFallback?: boolean } | { ok: false; reason: string } {
   248→  let entries: string[];
   249→  try {
   250→    entries = astParser.tableList(sql, { database: dialect === 'pg' ? 'PostgreSQL' : 'MySQL' });
   251→  } catch {
   252→    // P1-3：AST 解析失败放行（正则白名单已兜底），但标记 astFallback 供路由层审计
   253→    return { ok: true, astFallback: true };
   254→  }
   255→  for (const entry of entries) {
   256→    // 条目格式：`<action>::<db>::<table>`，如 `select::null::orders`
   257→    const [action, , table] = String(entry).split('::');
   258→    if (action !== 'select') {
   259→      return { ok: false, reason: `SQL 包含非只读操作（${action}）` };
   260→    }
   261→    if (table && table !== 'null' && !cteNames.has(table.toLowerCase()) && !allowedTables.has(table.toLowerCase())) {
   262→      return { ok: false, reason: `SQL 引用了问数范围外的表：${table}` };
   263→    }
   264→  }
   265→  return { ok: true };
   266→}
   267→
   268→/**
   269→ * 表名纠偏：LLM 常给白名单表名臆加 tbl_/t_ 前缀（导致白名单校验失败降级演示数据），
   270→ * 仅当去前缀后与白名单表名逐字一致时才整词替换回真实表名（不扩大也不缩小可执行范围）。
   271→ */
   272→export function repairTablePrefixes(sql: string, allowedTables: { name: string }[]): string {
   273→  let out = sql;
   274→  for (const t of allowedTables || []) {
   275→    const name = String(t?.name || '').trim();
   276→    if (!name) continue;
   277→    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
   278→    out = out.replace(new RegExp(`\\b(?:tbl_|t_)(\`${escaped}\`|${escaped})\\b`, 'gi'), (_m, g1: string) =>
   279→      g1.startsWith('`') ? `\`${name}\`` : name
   280→    );
   281→  }
   282→  return out;
   283→}
   284→
   285→/**
   286→ * 校验 LLM 生成的 SQL 是否允许对真实数据源执行。
   287→ * allowedTables：已通过 scope 白名单与敏感列过滤的 Schema（含列名清单）。
   288→ * sensitiveColumns：被剔除的敏感列名（裸列名），SQL 引用即拒绝。
   289→ * 通过时返回可能被追加/clamp LIMIT 的 SQL。
   290→ */
   291→export function validateSelectSql(
   292→  rawSqlInput: unknown,
   293→  allowedTables: { name: string; columns?: { name: string }[] }[],
   294→  sensitiveColumns: string[] = [],
   295→  dialect: SqlDialect = 'mysql',
   296→  maxRows: number = MAX_ROWS
   297→): SqlSafetyResult {
   298→  if (typeof rawSqlInput !== 'string' || !rawSqlInput.trim()) {
   299→    return { ok: false, reason: 'SQL 为空或格式无效' };
   300→  }
   301→  const rawSql = repairTablePrefixes(rawSqlInput, allowedTables);
   302→  const stripped = stripCommentsAndStrings(rawSql, dialect).trim().replace(/\s+/g, ' ');
   303→  // 结构安全校验基于 stripped（字符串已置空，防字面量内关键字干扰）；
   304→  // 但最终 SQL 必须保留字符串字面量值（如 WHERE region = '合肥市'），
   305→  // 只剥注释（否则空白归一后行尾注释会吞掉追加的 LIMIT）
   306→  const original = rawSql
   307→    .replace(/\/\*[\s\S]*?\*\//g, ' ')
   308→    .replace(/--[^\n]*/g, ' ')
   309→    .replace(/#[^\n]*/g, ' ')
   310→    .trim()
   311→    .replace(/\s+/g, ' ')
   312→    .replace(/;+\s*$/, '');
   313→  // 语句过长直接拒绝（防御畸形输出；v0.4.13 随路由层放宽至 10000）
   314→  if (stripped.length > 10000) {
   315→    return { ok: false, reason: 'SQL 长度超出限制' };
   316→  }
   317→  // 单语句：分号只允许出现在末尾
   318→  const withoutTrailing = stripped.replace(/;+\s*$/, '');
   319→  if (withoutTrailing.includes(';')) {
   320→    return { ok: false, reason: '只允许单条 SELECT 语句' };
   321→  }
   322→  // v0.4.15：WITH 开头（CTE）放行——正则无法确认 WITH 主体是 SELECT，交由 AST 强校验（解析失败 fail-closed）
   323→  const isWithCte = /^with\b/i.test(withoutTrailing);
   324→  if (!/^select\b/i.test(withoutTrailing) && !isWithCte) {
   325→    return { ok: false, reason: '只允许 SELECT 查询' };
   326→  }
   327→  // CTE 名是查询内临时结果集别名，白名单与 AST 表引用校验均须排除
   328→  const cteNames = extractCteNames(withoutTrailing);
   329→  if (/\binto\b/i.test(withoutTrailing)) {
   330→    return { ok: false, reason: '禁止 INTO 写文件/表操作' };
   331→  }
   332→  if (FORBIDDEN_PATTERN.test(withoutTrailing)) {
   333→    return { ok: false, reason: 'SQL 包含不允许的关键字（仅支持只读查询）' };
   334→  }
   335→  // 表名白名单
   336→  const allowed = new Set(allowedTables.map((t) => String(t.name || '').toLowerCase()));
   337→  const refs = extractTableRefs(withoutTrailing).filter((r) => !cteNames.has(r));
   338→  if (refs.length === 0) {
   339→    return { ok: false, reason: 'SQL 未引用任何数据表' };
   340→  }
   341→  const illegal = refs.filter((r) => !allowed.has(r));
   342→  if (illegal.length > 0) {
   343→    return { ok: false, reason: `SQL 引用了问数范围外的表：${illegal.join(', ')}` };
   344→  }
   345→  // P1 AST 二道防线（正则白名单之后）：语法树级复核语句类型与表引用
   346→  const astCheck = checkAstSafety(withoutTrailing, allowed, dialect, cteNames);
   347→  if (astCheck.ok !== true) {
   348→    return { ok: false, reason: astCheck.reason };
   349→  }
   350→  // WITH 开头必须 AST 解析成功：正则防线无法确认 WITH 主体是 SELECT，解析失败时无兜底，fail-closed
   351→  if (isWithCte && astCheck.astFallback === true) {
   352→    return { ok: false, reason: 'WITH 查询无法完成语法解析确认，已拒绝执行' };
   353→  }
   354→  const astFallback = astCheck.astFallback === true;
   355→  // 敏感列拒绝（裸列名整词匹配，覆盖反引号写法）
   356→  for (const col of sensitiveColumns) {
   357→    const name = String(col).split('.').pop() || '';
   358→    if (!name) continue;
   359→    const re = new RegExp(`\\b${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i');
   360→    if (re.test(withoutTrailing)) {
   361→      return { ok: false, reason: `SQL 涉及受保护的敏感字段：${name}` };
   362→    }
   363→  }
   364→  // 强制 LIMIT：无 LIMIT 追加；有 LIMIT 则将返回行数 clamp 到 MAX_ROWS（v0.4.14 放宽至 10 万）
   365→  // 方言差异：MySQL 支持 LIMIT offset,count；PG/Greenplum 仅支持 LIMIT n OFFSET m
   366→  // 注意：基于原文操作，保证字符串字面量（如 WHERE region = '合肥市'）不被篡改
   367→  let finalSql = original;
   368→  const limitRe = /\blimit\s+(\d+)(?:\s*,\s*(\d+)|\s+offset\s+(\d+))?\s*$/i;
   369→  const lm = finalSql.match(limitRe);
   370→  if (!lm) {
   371→    finalSql = `${finalSql} LIMIT ${maxRows}`;
   372→  } else {
   373→    const count = lm[2] ? Number(lm[2]) : Number(lm[1]);
   374→    const offset = lm[2] ? Number(lm[1]) : lm[3] ? Number(lm[3]) : 0;
   375→    const clamped = Math.min(count, maxRows);
   376→    const replacement =
   377→      dialect === 'pg'
   378→        ? offset > 0
   379→          ? `LIMIT ${clamped} OFFSET ${offset}`
   380→          : `LIMIT ${clamped}`
   381→        : offset > 0
   382→          ? `LIMIT ${offset}, ${clamped}`
   383→          : `LIMIT ${clamped}`;
   384→    finalSql = finalSql.replace(limitRe, replacement);
   385→  }
   386→  return { ok: true, sql: finalSql, astFallback };
   387→}
   388→
   389→/**
   390→ * P1-3 行级权限：把带行过滤的表在 AST 中包裹为过滤子查询
   391→ * （FROM clients → FROM (SELECT * FROM clients WHERE <谓词>) AS clients），
   392→ * 递归覆盖子查询/UNION 内的引用。谓词解析失败或 AST 回写失败均 fail-closed 拒绝，
   393→ * 安全优先于可用性（此时问数降级演示模式，不泄露受限行）。
   394→ * rowFilters 键为小写实际表名；SQL 未引用受控表时原样返回。
   395→ */
   396→export function injectRowFilters(
   397→  sql: string,
   398→  rowFilters: Record<string, string>,
   399→  dialect: SqlDialect = 'mysql'
   400→): SqlSafetyResult {
   401→  const lower: Record<string, string> = {};
   402→  for (const [name, pred] of Object.entries(rowFilters)) {
   403→    if (name && pred) lower[name.toLowerCase()] = pred;
   404→  }
   405→  if (Object.keys(lower).length === 0) return { ok: true, sql };
   406→
   407→  const stripped = stripCommentsAndStrings(sql, dialect);
   408→  const refs = extractTableRefs(stripped.replace(/;+\s*$/, ''));
   409→  if (!refs.some((r) => lower[r])) return { ok: true, sql };
   410→
   411→  const opt = { database: dialect === 'pg' ? 'PostgreSQL' : 'MySQL' };
   412→  try {
   413→    const parsed: any = astParser.astify(sql, opt);
   414→
   415→    // 谓词 → 派生表 expr：解析 `SELECT * FROM (SELECT * FROM t WHERE pred) AS t`
   416→    // 直接复用解析产物（而非手工拼 AST），保证 sqlify 回写时派生表带括号；
   417→    // 谓词非法自然抛错，fail-closed。
   418→    const wrappedOf = (table: string, pred: string): any => {
   419→      const helper: any = astParser.astify(`SELECT * FROM (SELECT * FROM ${table} WHERE ${pred}) AS ${table}`, opt);
   420→      const h = Array.isArray(helper) ? helper[0] : helper;
   421→      const item = h && Array.isArray(h.from) ? h.from[0] : null;
   422→      if (!item || !item.expr) throw new Error('谓词解析失败');
   423→      return item.expr;
   424→    };
   425→
   426→    const wrapFrom = (from: any): void => {
   427→      if (!Array.isArray(from)) return;
   428→      for (const item of from) {
   429→        if (!item) continue;
   430→        // 派生表（FROM (SELECT ...)）递归下钻：5.x 为 { ast, parentheses } 包裹层，旧版直接是 select 节点
   431→        if (item.expr && typeof item.expr === 'object') {
   432→          const inner = item.expr.ast && typeof item.expr.ast === 'object' ? item.expr.ast : item.expr;
   433→          walkNode(inner);
   434→        }
   435→        const tableName = typeof item.table === 'string' ? item.table : '';
   436→        const pred = tableName ? lower[tableName.toLowerCase()] : undefined;
   437→        if (!pred) continue;
   438→        // 未显式起别名时补上原表名，保证外层列引用不变
   439→        if (!item.as) item.as = tableName;
   440→        item.expr = wrappedOf(tableName, pred);
   441→        item.table = null;
   442→        item.db = null;
   443→      }
   444→    };
   445→    const walkNode = (node: any): void => {
   446→      if (!node || typeof node !== 'object') return;
   447→      if (Array.isArray(node)) {
   448→        node.forEach(walkNode);
   449→        return;
   450→      }
   451→      if (node.type === 'select') {
   452→        wrapFrom(node.from);
   453→        // v0.4.15：WITH CTE 定义内的真实表引用也须包裹行过滤——ast.with[i].stmt.ast 为各 CTE 子查询 AST，
   454→        // 不递归会导致 CTE 内受控表静默漏注（越权读）；CTE 名本身不在 rowFilters 键中，主查询引用 CTE 不受影响
   455→        if (Array.isArray(node.with)) {
   456→          for (const cte of node.with) {
   457→            if (cte && cte.stmt && typeof cte.stmt === 'object') walkNode(cte.stmt.ast);
   458→          }
   459→        }
   460→        // WHERE/HAVING 等表达式中的子查询（IN (SELECT ...)、EXISTS 等）
   461→        walkExprSubqueries(node.where);
   462→        walkExprSubqueries(node.having);
   463→        // UNION/UNION ALL 链（node-sql-parser 5.x 用 _next 链 + set_op）
   464→        if (node._next) walkNode(node._next);
   465→      }
   466→    };
   467→    const walkExprSubqueries = (expr: any): void => {
   468→      if (!expr || typeof expr !== 'object') return;
   469→      if (Array.isArray(expr)) {
   470→        expr.forEach(walkExprSubqueries);
   471→        return;
   472→      }
   473→      if (expr.ast && typeof expr.ast === 'object') walkNode(expr.ast);
   474→      walkExprSubqueries(expr.left);
   475→      walkExprSubqueries(expr.right);
   476→      if (expr.value !== undefined) walkExprSubqueries(expr.value);
   477→      if (Array.isArray(expr.args)) walkExprSubqueries(expr.args);
   478→    };
   479→
   480→    walkNode(Array.isArray(parsed) ? parsed[0] : parsed);
   481→    const rewritten = astParser.sqlify(parsed, opt);
   482→    if (typeof rewritten !== 'string' || !rewritten.trim()) {
   483→      return { ok: false, reason: '行级权限注入失败，已拒绝该查询' };
   484→    }
   485→    return { ok: true, sql: rewritten };
   486→  } catch {
   487→    return { ok: false, reason: '行级权限注入失败，已拒绝该查询' };
   488→  }
