   565→export function parseMysqlExplainRows(explainRows: Record<string, unknown>[]): number {
   566→  const list = Array.isArray(explainRows) ? explainRows : [];
   567→  let max = 0;
   568→  // 形态 1：传统表格多列（含数值 rows 字段）
   569→  for (const r of list) {
   570→    const v = Number(r?.rows);
   571→    if (Number.isFinite(v) && v > max) max = v;
   572→  }
   573→  if (max > 0) return max;
   574→  // 形态 2/3：单列 EXPLAIN 文本（JSON 或树形）
   575→  const text = list.length > 0 ? list[0]?.EXPLAIN : null;
