    36→  if (dsType === 'greenplum') return { label: 'Greenplum（PostgreSQL 兼容方言）', rules: '- 方言要点：分页仅支持 LIMIT n OFFSET m；标识符用双引号；日期用 EXTRACT/date_trunc；空值用 COALESCE；字符串拼接用 ||；分组聚合用 STRING_AGG' };
    37→  if (dsType === 'postgresql') return { label: 'PostgreSQL', rules: '- 方言要点：分页仅支持 LIMIT n OFFSET m；标识符用双引号；日期用 EXTRACT/date_trunc；空值用 COALESCE；字符串拼接用 ||；分组聚合用 STRING_AGG' };
    38→  return { label: 'MySQL', rules: '' };
    39→}
    40→
    41→const MAX_ROWS = 100000; // v0.4.14：500→100000，满足真实记录数输出，保留兜底防 OOM
    42→const CONNECT_TIMEOUT_MS = 5_000;
    43→
    44→/**
    45→ * P1-9 数据源连接池容量公式化（原硬编码 max=3）。
    46→ * 容量模型：每次问数仅在 SQL 执行阶段持有连接（秒级，QUERY_TIMEOUT_MS 兜底），
    47→ * 端到端延迟由 LLM 生成主导（数十秒级），故数据源连接并发 ≈ 并发用户数 / 4。
    48→ * DS_POOL_MAX 显式配置优先；否则按 EXPECTED_CONCURRENT_USERS 推导，clamp 到 [3, 20]
    49→ * （下限不逊于原硬编码水位，上限防止打爆数据源端 max_connections）。
    50→ */
    51→export function dsPoolMax(): number {
    52→  const raw = process.env.DS_POOL_MAX;
    53→  if (raw !== undefined && raw.trim() !== '') {
    54→    const n = Number(raw);
    55→    if (Number.isFinite(n) && n >= 1) return Math.min(100, Math.floor(n));
    56→  }
    57→  const users = Number(process.env.EXPECTED_CONCURRENT_USERS) || 20;
    58→  return Math.min(20, Math.max(3, Math.ceil(users / 4)));
    59→}
    60→
    61→/**
    62→ * P2-4 查询场景分级：连接池配额与执行超时按场景独立配置。
    63→ * - interactive：交互问数/下钻/指标预览（用户在线等待，默认超时 15s）
    64→ * - chain：分析链/报表生成等多 SQL 链路（默认超时 120s，配额减半）
    65→ * - export：异步报告/导出类后台任务（默认超时 60s，配额最小，占满不挤占交互）
    66→ */
    67→export type QueryScenario = 'interactive' | 'chain' | 'export';
    68→
    69→function envPositiveInt(name: string): number | null {
    70→  const raw = process.env[name];
    71→  if (raw === undefined || raw.trim() === '') return null;
    72→  const n = Number(raw);
    73→  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : null;
    74→}
    75→
    76→/**
    77→ * 场景化连接池配额：DS_POOL_MAX=10 时恰为 交互10 / 分析链5 / 导出2（改进计划 2-4 基准）。
    78→ * 显式 env 优先：DS_POOL_INTERACTIVE / DS_POOL_CHAIN / DS_POOL_EXPORT（clamp 到 [1, 100]）。
    79→ */
    80→export function dsPoolScenarioMax(scenario: QueryScenario): number {
    81→  const base = dsPoolMax();
    82→  const explicit =
    83→    scenario === 'chain'
    84→      ? envPositiveInt('DS_POOL_CHAIN')
    85→      : scenario === 'export'
    86→        ? envPositiveInt('DS_POOL_EXPORT')
    87→        : envPositiveInt('DS_POOL_INTERACTIVE');
    88→  if (explicit !== null) return Math.min(100, explicit);
    89→  if (scenario === 'chain') return Math.max(2, Math.ceil(base / 2));
    90→  if (scenario === 'export') return Math.max(1, Math.floor(base / 5));
    91→  return base;
    92→}
    93→
    94→/**
    95→ * 场景化执行超时（毫秒）：交互 15s / 分析链 120s / 导出 60s。
    96→ * 显式 env 优先：QUERY_TIMEOUT_INTERACTIVE_MS / QUERY_TIMEOUT_CHAIN_MS / QUERY_TIMEOUT_EXPORT_MS。
    97→ */
    98→export function scenarioTimeoutMs(scenario: QueryScenario): number {
    99→  const explicit =
   100→    scenario === 'chain'
   101→      ? envPositiveInt('QUERY_TIMEOUT_CHAIN_MS')
   102→      : scenario === 'export'
   103→        ? envPositiveInt('QUERY_TIMEOUT_EXPORT_MS')
   104→        : envPositiveInt('QUERY_TIMEOUT_INTERACTIVE_MS');
   105→  if (explicit !== null) return explicit;
   106→  if (scenario === 'chain') return 120_000;
   107→  if (scenario === 'export') return 60_000;
   108→  return 15_000;
   109→}
   110→
   111→/**
   112→ * MySQL 服务端执行时限：在 SELECT 开头注入优化器提示 MAX_EXECUTION_TIME(n)（hint 注释形式，毫秒）。
   113→ * 仅作用于 SELECT（本层已保证 SELECT-only）；MySQL 5.7.8+ 生效，老版本将其当注释安全忽略。
   114→ * 注意必须在全部校验/行权限注入之后、执行之前追加（AST 解析器不认 hint 注释，提前注入会被 fail-closed 误拦）。
   115→ * v0.4.15：WITH 开头（CTE）时 hint 须注入 CTE 链之后的主 SELECT——括号配平扫描定位最后一个
   116→ * CTE 定义的闭合右括号，其后即主查询；定位失败原样返回（驱动层 query timeout 仍兜底，不阻断查询）。
   117→ */
   118→export function injectMysqlMaxExecTime(sql: string, timeoutMs: number): string {
   119→  const ms = Math.max(1, Math.floor(timeoutMs));
   120→  if (/^\s*with\b/i.test(sql)) {
   121→    let depth = 0;
   122→    let inStr = false;
   123→    let chainEnd = -1;
   124→    for (let i = sql.indexOf('('); i >= 0 && i < sql.length; i++) {
   125→      const ch = sql[i];
   126→      if (ch === "'") inStr = !inStr; // '' 转义连续翻转两次净效果正确；配平失败仅降级为不注入 hint
   127→      if (inStr) continue;
   128→      if (ch === '(') depth++;
   129→      else if (ch === ')') {
   130→        depth--;
   131→        if (depth === 0) {
   132→          // CTE 定义闭合：后续是 `, name AS (` 则还有下一段 CTE，否则链结束
   133→          const nextCte = sql.slice(i + 1).match(/^\s*,\s*[`"\w]+\s+as\s*\(/i);
   134→          if (nextCte) {
   135→            // 让 for 的 i++ 恰好落在下一个 CTE 的左括号上（depth++ 不错漏）
   136→            i += nextCte[0].length - 1;
   137→            continue;
   138→          }
   139→          chainEnd = i;
   140→          break;
   141→        }
   142→      }
   143→    }
   144→    if (chainEnd >= 0) {
   145→      const tail = sql.slice(chainEnd + 1);
   146→      if (/^\s*select\b/i.test(tail)) {
   147→        return sql.slice(0, chainEnd + 1) + tail.replace(/^(\s*)select\b/i, `$1SELECT /*+ MAX_EXECUTION_TIME(${ms}) */`);
   148→      }
   149→    }
   150→    return sql;
   151→  }
   152→  return sql.replace(/^\s*select\b/i, `SELECT /*+ MAX_EXECUTION_TIME(${ms}) */`);
   153→}
   154→
   155→// 写/DDL/管理类关键字一律拒绝（对剥离注释与字符串后的 SQL 做整词匹配）。
   156→// 注意词表必须避开合法 SELECT 语法内会出现的词：desc（ORDER BY DESC）、replace/use/set/do/call/check/load/show
   157→// 等不在此列——这些语句本就无法出现在 SELECT 内部，"只允许 SELECT 开头"一层已拦截。
   158→// procedure 在列：PROCEDURE ANALYSE 是 SELECT 内真实存在的危险构造。
   159→const FORBIDDEN_PATTERN =
   160→  /\b(insert|update|delete|drop|alter|truncate|create|grant|revoke|rename|lock|unlock|exec|execute|outfile|infile|dumpfile|procedure|explain|handler|install|uninstall|kill|shutdown|analyze|optimize|repair|checksum|flush|reset|purge|binlog|prepare|deallocate|release|savepoint|rollback|commit|begin|xa)\b/i;
   161→
   162→/** M3 应用库中间表查询校验复用同一危险关键字词表 */
   163→export const FORBIDDEN_KEYWORD_RE = FORBIDDEN_PATTERN;
   164→
   165→// 注意：项目 tsconfig 未开启 strictNullChecks，真值窄化（if (!x.ok)）对判别联合不生效，
   166→// 所有使用处必须用 x.ok !== true / x.ok === false 的显式比较（同 queryGuard 的先例）。
   167→export type SqlSafetyResult = { ok: true; sql: string; astFallback?: boolean } | { ok: false; reason: string };
   168→
   169→/**
   170→ * 剥离单行/块注释与字符串字面量，避免注释或字符串中的关键字干扰结构校验。
   171→ * dialect='pg' 时保留双引号段：PostgreSQL/Greenplum 双引号是标识符（表名/列名），
   172→ * 若当字符串字面量剥掉，表引用提取会丢失 FROM 目标，导致合法 PG SQL 被误拦（v0.9.1 修复）。
   173→ */
   174→export function stripCommentsAndStrings(sql: string, dialect: SqlDialect = 'mysql'): string {
   175→  const out = sql
   176→    .replace(/\/\*[\s\S]*?\*\//g, ' ')
   177→    .replace(/--[^\n]*/g, ' ')
   178→    .replace(/#[^\n]*/g, ' ')
   179→    .replace(/'(?:[^'\\]|\\.|'')*'/g, "''");
   180→  // MySQL 默认模式下双引号等同字符串字面量（非 ANSI_QUOTES），剥掉防关键字干扰
   181→  return dialect === 'pg' ? out : out.replace(/"(?:[^"\\]|\\.)*"/g, '""');
   182→}
   183→
   184→function cleanIdent(raw: string): string {
   185→  const stripped = raw.replace(/[`"]/g, '');
   186→  const parts = stripped.split('.');
   187→  return (parts[parts.length - 1] || '').trim().toLowerCase();
   188→}
   189→
   190→/**
   191→ * 提取 SQL 中 FROM/JOIN 引用的全部表名（含子查询，支持反引号与库名前缀、逗号分隔多表）。
   192→ * 返回小写表名清单（不含库名前缀）。
   193→ */
   194→export function extractTableRefs(strippedSql: string): string[] {
   195→  const refs = new Set<string>();
   196→  const KEYWORDS = /^(select|where|on|using|left|right|inner|outer|cross|natural|straight_join|as|join|full)$/i;
   197→
   198→  // 主扫描：逐个命中 FROM/JOIN 后紧跟的标识符（全局扫描天然覆盖子查询内部的 FROM）
   199→  const direct = /\b(?:from|join)\s+([`"\w.]+)/gi;
   200→  let m: RegExpExecArray | null;
   201→  while ((m = direct.exec(strippedSql))) {
   202→    if (!KEYWORDS.test(m[1])) refs.add(cleanIdent(m[1]));
   203→  }
   204→  // 补充：FROM 子句内逗号分隔的多表（JOIN 链已由主扫描覆盖；到子句终止或右括号为止）
   205→  const fromSeg = /\bfrom\b([\s\S]*?)(?=\bwhere\b|\bgroup\s+by\b|\border\s+by\b|\blimit\b|\bhaving\b|\bunion\b|\)|;|$)/gi;
   206→  while ((m = fromSeg.exec(strippedSql))) {
   207→    // 段内含括号（子查询/函数）时逗号分表不可靠：子查询 SELECT 列表的逗号会把列名/聚合函数名
   208→    // （如 SUM/BNTFJE）误当表名拒拦合法 SQL；子查询内部真实表已由主扫描 FROM/JOIN 命中覆盖
   209→    if (/[()]/.test(m[1])) continue;
   210→    for (const slotRaw of m[1].split(',')) {
   211→      const slot = slotRaw.split(/\bon\b|\busing\b/i)[0];
   212→      const lead = slot.trimStart().match(/^([`"\w.]+)/);
   213→      if (!lead || KEYWORDS.test(lead[1])) continue; // 子查询 (SELECT...) 由主扫描覆盖其内部表
   214→      refs.add(cleanIdent(lead[1]));
   215→    }
   216→  }
   217→  refs.delete('');
   218→  return [...refs];
   219→}
   220→
   221→/**
   222→ * v0.4.15 复杂 SQL（CTE 放行）：提取 WITH 链定义的 CTE 名集合（入参为剥离字符串后的 SQL）。
   223→ * CTE 名是查询内临时结果集别名而非真实表，表名白名单与 AST 复核均须排除，否则合法 CTE 被误拦。
   224→ * 仅 WITH 开头时有值；`name AS (` 结构不会出现在 SELECT 列列表（别名后不跟左括号），正则安全。
   225→ */
   226→export function extractCteNames(strippedSql: string): Set<string> {
   227→  const names = new Set<string>();
   228→  if (!/^\s*with\b/i.test(strippedSql)) return names;
   229→  const re = /(?:\bwith|,)\s*([`"\w]+)\s+as\s*\(/gi;
   230→  let m: RegExpExecArray | null;
   231→  while ((m = re.exec(strippedSql))) {
   232→    names.add(m[1].replace(/[`"]/g, '').toLowerCase());
   233→  }
   234→  return names;
   235→}
   236→
   237→// P1 AST 二道防线：node-sql-parser 语法树级复核。
   238→// 解析成功 → 强校验（所有语句类型必须为 select、AST 提取的表必须全在白名单）；
   239→// 解析失败 → 放行不误伤（MySQL 方言边界），此时第一道正则防线的结论已生效。
   240→// v0.4.15：cteNames 为 WITH 链定义的 CTE 名（临时结果集别名），tableList 会将其误报为表，须排除。
   241→const astParser = new SqlAstParser();
   242→export function checkAstSafety(
   243→  sql: string,
   244→  allowedTables: Set<string>,
   245→  dialect: SqlDialect = 'mysql',
   246→  cteNames: Set<string> = new Set()
   247→): { ok: true; astFallback?: boolean } | { ok: false; reason: string } {
   248→  let entries: string[];
   249→  try {
   250→    entries = astParser.tableList(sql, { database: dialect === 'pg' ? 'PostgreSQL' : 'MySQL' });
   251→  } catch {
   252→    // P1-3：AST 解析失败放行（正则白名单已兜底），但标记 astFallback 供路由层审计
   253→    return { ok: true, astFallback: true };
   254→  }
   255→  for (const entry of entries) {
   256→    // 条目格式：`<action>::<db>::<table>`，如 `select::null::orders`
   257→    const [action, , table] = String(entry).split('::');
   258→    if (action !== 'select') {
   259→      return { ok: false, reason: `SQL 包含非只读操作（${action}）` };
   260→    }
   261→    if (table && table !== 'null' && !cteNames.has(table.toLowerCase()) && !allowedTables.has(table.toLowerCase())) {
   262→      return { ok: false, reason: `SQL 引用了问数范围外的表：${table}` };
   263→    }
   264→  }
   265→  return { ok: true };
   266→}
   267→
   268→/**
   269→ * 表名纠偏：LLM 常给白名单表名臆加 tbl_/t_ 前缀（导致白名单校验失败降级演示数据），
   270→ * 仅当去前缀后与白名单表名逐字一致时才整词替换回真实表名（不扩大也不缩小可执行范围）。
   271→ */
   272→export function repairTablePrefixes(sql: string, allowedTables: { name: string }[]): string {
   273→  let out = sql;
   274→  for (const t of allowedTables || []) {
   275→    const name = String(t?.name || '').trim();
   276→    if (!name) continue;
   277→    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
   278→    out = out.replace(new RegExp(`\\b(?:tbl_|t_)(\`${escaped}\`|${escaped})\\b`, 'gi'), (_m, g1: string) =>
   279→      g1.startsWith('`') ? `\`${name}\`` : name
   280→    );
   281→  }
   282→  return out;
   283→}
   284→
   285→/**
   286→ * 校验 LLM 生成的 SQL 是否允许对真实数据源执行。
   287→ * allowedTables：已通过 scope 白名单与敏感列过滤的 Schema（含列名清单）。
   288→ * sensitiveColumns：被剔除的敏感列名（裸列名），SQL 引用即拒绝。
   289→ * 通过时返回可能被追加/clamp LIMIT 的 SQL。
   290→ */
   291→export function validateSelectSql(
   292→  rawSqlInput: unknown,
   293→  allowedTables: { name: string; columns?: { name: string }[] }[],
   294→  sensitiveColumns: string[] = [],
   295→  dialect: SqlDialect = 'mysql',
   296→  maxRows: number = MAX_ROWS
   297→): SqlSafetyResult {
   298→  if (typeof rawSqlInput !== 'string' || !rawSqlInput.trim()) {
   299→    return { ok: false, reason: 'SQL 为空或格式无效' };
   300→  }
   301→  const rawSql = repairTablePrefixes(rawSqlInput, allowedTables);
   302→  const stripped = stripCommentsAndStrings(rawSql, dialect).trim().replace(/\s+/g, ' ');
   303→  // 结构安全校验基于 stripped（字符串已置空，防字面量内关键字干扰）；
   304→  // 但最终 SQL 必须保留字符串字面量值（如 WHERE region = '合肥市'），
   305→  // 只剥注释（否则空白归一后行尾注释会吞掉追加的 LIMIT）
   306→  const original = rawSql
   307→    .replace(/\/\*[\s\S]*?\*\//g, ' ')
   308→    .replace(/--[^\n]*/g, ' ')
   309→    .replace(/#[^\n]*/g, ' ')
   310→    .trim()
   311→    .replace(/\s+/g, ' ')
   312→    .replace(/;+\s*$/, '');
   313→  // 语句过长直接拒绝（防御畸形输出；v0.4.13 随路由层放宽至 10000）
   314→  if (stripped.length > 10000) {
   315→    return { ok: false, reason: 'SQL 长度超出限制' };
   316→  }
   317→  // 单语句：分号只允许出现在末尾
   318→  const withoutTrailing = stripped.replace(/;+\s*$/, '');
   319→  if (withoutTrailing.includes(';')) {
   320→    return { ok: false, reason: '只允许单条 SELECT 语句' };
   321→  }
   322→  // v0.4.15：WITH 开头（CTE）放行——正则无法确认 WITH 主体是 SELECT，交由 AST 强校验（解析失败 fail-closed）
   323→  const isWithCte = /^with\b/i.test(withoutTrailing);
   324→  if (!/^select\b/i.test(withoutTrailing) && !isWithCte) {
   325→    return { ok: false, reason: '只允许 SELECT 查询' };
   326→  }
   327→  // CTE 名是查询内临时结果集别名，白名单与 AST 表引用校验均须排除
   328→  const cteNames = extractCteNames(withoutTrailing);
   329→  if (/\binto\b/i.test(withoutTrailing)) {
   330→    return { ok: false, reason: '禁止 INTO 写文件/表操作' };
   331→  }
   332→  if (FORBIDDEN_PATTERN.test(withoutTrailing)) {
   333→    return { ok: false, reason: 'SQL 包含不允许的关键字（仅支持只读查询）' };
   334→  }
   335→  // 表名白名单
   336→  const allowed = new Set(allowedTables.map((t) => String(t.name || '').toLowerCase()));
   337→  const refs = extractTableRefs(withoutTrailing).filter((r) => !cteNames.has(r));
   338→  if (refs.length === 0) {
   339→    return { ok: false, reason: 'SQL 未引用任何数据表' };
   340→  }
   341→  const illegal = refs.filter((r) => !allowed.has(r));
   342→  if (illegal.length > 0) {
   343→    return { ok: false, reason: `SQL 引用了问数范围外的表：${illegal.join(', ')}` };
   344→  }
   345→  // P1 AST 二道防线（正则白名单之后）：语法树级复核语句类型与表引用
   346→  const astCheck = checkAstSafety(withoutTrailing, allowed, dialect, cteNames);
   347→  if (astCheck.ok !== true) {
   348→    return { ok: false, reason: astCheck.reason };
   349→  }
   350→  // WITH 开头必须 AST 解析成功：正则防线无法确认 WITH 主体是 SELECT，解析失败时无兜底，fail-closed
   351→  if (isWithCte && astCheck.astFallback === true) {
   352→    return { ok: false, reason: 'WITH 查询无法完成语法解析确认，已拒绝执行' };
   353→  }
   354→  const astFallback = astCheck.astFallback === true;
   355→  // 敏感列拒绝（裸列名整词匹配，覆盖反引号写法）
   356→  for (const col of sensitiveColumns) {
   357→    const name = String(col).split('.').pop() || '';
   358→    if (!name) continue;
   359→    const re = new RegExp(`\\b${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i');
   360→    if (re.test(withoutTrailing)) {
   361→      return { ok: false, reason: `SQL 涉及受保护的敏感字段：${name}` };
   362→    }
   363→  }
   364→  // 强制 LIMIT：无 LIMIT 追加；有 LIMIT 则将返回行数 clamp 到 MAX_ROWS（v0.4.14 放宽至 10 万）
   365→  // 方言差异：MySQL 支持 LIMIT offset,count；PG/Greenplum 仅支持 LIMIT n OFFSET m
   366→  // 注意：基于原文操作，保证字符串字面量（如 WHERE region = '合肥市'）不被篡改
   367→  let finalSql = original;
   368→  const limitRe = /\blimit\s+(\d+)(?:\s*,\s*(\d+)|\s+offset\s+(\d+))?\s*$/i;
   369→  const lm = finalSql.match(limitRe);
   370→  if (!lm) {
   371→    finalSql = `${finalSql} LIMIT ${maxRows}`;
   372→  } else {
   373→    const count = lm[2] ? Number(lm[2]) : Number(lm[1]);
   374→    const offset = lm[2] ? Number(lm[1]) : lm[3] ? Number(lm[3]) : 0;
   375→    const clamped = Math.min(count, maxRows);
   376→    const replacement =
   377→      dialect === 'pg'
   378→        ? offset > 0
   379→          ? `LIMIT ${clamped} OFFSET ${offset}`
   380→          : `LIMIT ${clamped}`
   381→        : offset > 0
   382→          ? `LIMIT ${offset}, ${clamped}`
   383→          : `LIMIT ${clamped}`;
   384→    finalSql = finalSql.replace(limitRe, replacement);
   385→  }
   386→  return { ok: true, sql: finalSql, astFallback };
   387→}
   388→
   389→/**
   390→ * P1-3 行级权限：把带行过滤的表在 AST 中包裹为过滤子查询
   391→ * （FROM clients → FROM (SELECT * FROM clients WHERE <谓词>) AS clients），
   392→ * 递归覆盖子查询/UNION 内的引用。谓词解析失败或 AST 回写失败均 fail-closed 拒绝，
   393→ * 安全优先于可用性（此时问数降级演示模式，不泄露受限行）。
   394→ * rowFilters 键为小写实际表名；SQL 未引用受控表时原样返回。
   395→ */
   396→export function injectRowFilters(
   397→  sql: string,
   398→  rowFilters: Record<string, string>,
   399→  dialect: SqlDialect = 'mysql'
   400→): SqlSafetyResult {
   401→  const lower: Record<string, string> = {};
   402→  for (const [name, pred] of Object.entries(rowFilters)) {
   403→    if (name && pred) lower[name.toLowerCase()] = pred;
   404→  }
   405→  if (Object.keys(lower).length === 0) return { ok: true, sql };
   406→
   407→  const stripped = stripCommentsAndStrings(sql, dialect);
   408→  const refs = extractTableRefs(stripped.replace(/;+\s*$/, ''));
   409→  if (!refs.some((r) => lower[r])) return { ok: true, sql };
   410→
   411→  const opt = { database: dialect === 'pg' ? 'PostgreSQL' : 'MySQL' };
   412→  try {
   413→    const parsed: any = astParser.astify(sql, opt);
   414→
   415→    // 谓词 → 派生表 expr：解析 `SELECT * FROM (SELECT * FROM t WHERE pred) AS t`
   416→    // 直接复用解析产物（而非手工拼 AST），保证 sqlify 回写时派生表带括号；
   417→    // 谓词非法自然抛错，fail-closed。
   418→    const wrappedOf = (table: string, pred: string): any => {
   419→      const helper: any = astParser.astify(`SELECT * FROM (SELECT * FROM ${table} WHERE ${pred}) AS ${table}`, opt);
   420→      const h = Array.isArray(helper) ? helper[0] : helper;
   421→      const item = h && Array.isArray(h.from) ? h.from[0] : null;
   422→      if (!item || !item.expr) throw new Error('谓词解析失败');
   423→      return item.expr;
   424→    };
   425→
   426→    const wrapFrom = (from: any): void => {
   427→      if (!Array.isArray(from)) return;
   428→      for (const item of from) {
   429→        if (!item) continue;
   430→        // 派生表（FROM (SELECT ...)）递归下钻：5.x 为 { ast, parentheses } 包裹层，旧版直接是 select 节点
   431→        if (item.expr && typeof item.expr === 'object') {
   432→          const inner = item.expr.ast && typeof item.expr.ast === 'object' ? item.expr.ast : item.expr;
   433→          walkNode(inner);
   434→        }
   435→        const tableName = typeof item.table === 'string' ? item.table : '';
   436→        const pred = tableName ? lower[tableName.toLowerCase()] : undefined;
   437→        if (!pred) continue;
   438→        // 未显式起别名时补上原表名，保证外层列引用不变
   439→        if (!item.as) item.as = tableName;
   440→        item.expr = wrappedOf(tableName, pred);
   441→        item.table = null;
   442→        item.db = null;
   443→      }
   444→    };
   445→    const walkNode = (node: any): void => {
   446→      if (!node || typeof node !== 'object') return;
   447→      if (Array.isArray(node)) {
   448→        node.forEach(walkNode);
   449→        return;
   450→      }
   451→      if (node.type === 'select') {
   452→        wrapFrom(node.from);
   453→        // v0.4.15：WITH CTE 定义内的真实表引用也须包裹行过滤——ast.with[i].stmt.ast 为各 CTE 子查询 AST，
   454→        // 不递归会导致 CTE 内受控表静默漏注（越权读）；CTE 名本身不在 rowFilters 键中，主查询引用 CTE 不受影响
   455→        if (Array.isArray(node.with)) {
   456→          for (const cte of node.with) {
   457→            if (cte && cte.stmt && typeof cte.stmt === 'object') walkNode(cte.stmt.ast);
   458→          }
   459→        }
   460→        // WHERE/HAVING 等表达式中的子查询（IN (SELECT ...)、EXISTS 等）
   461→        walkExprSubqueries(node.where);
   462→        walkExprSubqueries(node.having);
   463→        // UNION/UNION ALL 链（node-sql-parser 5.x 用 _next 链 + set_op）
   464→        if (node._next) walkNode(node._next);
   465→      }
   466→    };
   467→    const walkExprSubqueries = (expr: any): void => {
   468→      if (!expr || typeof expr !== 'object') return;
   469→      if (Array.isArray(expr)) {
   470→        expr.forEach(walkExprSubqueries);
   471→        return;
   472→      }
   473→      if (expr.ast && typeof expr.ast === 'object') walkNode(expr.ast);
   474→      walkExprSubqueries(expr.left);
   475→      walkExprSubqueries(expr.right);
   476→      if (expr.value !== undefined) walkExprSubqueries(expr.value);
   477→      if (Array.isArray(expr.args)) walkExprSubqueries(expr.args);
   478→    };
   479→
   480→    walkNode(Array.isArray(parsed) ? parsed[0] : parsed);
   481→    const rewritten = astParser.sqlify(parsed, opt);
   482→    if (typeof rewritten !== 'string' || !rewritten.trim()) {
   483→      return { ok: false, reason: '行级权限注入失败，已拒绝该查询' };
   484→    }
   485→    return { ok: true, sql: rewritten };
   486→  } catch {
   487→    return { ok: false, reason: '行级权限注入失败，已拒绝该查询' };
   488→  }
   489→}
   490→
   491→// ---- 数据源连接池（P2-4：按 数据源ID+场景 分级缓存；mysql 走 mysql2，PG 系走 pg 驱动） ----
   492→type DsPoolEntry = { dialect: 'mysql'; pool: mysql.Pool } | { dialect: 'pg'; pool: pg.Pool };
   493→const dsPools = new Map<string, DsPoolEntry>();
   494→
   495→function dsPoolKey(dataSourceId: string, scenario: QueryScenario): string {
   496→  return `${dataSourceId}::${scenario}`;
   497→}
   498→
   499→/** 数据源配置变更/删除后调用，使该数据源的全部场景连接池失效 */
   500→export function invalidateExecutorPool(dataSourceId?: string): void {
   501→  if (dataSourceId) {
   502→    const prefix = `${dataSourceId}::`;
   503→    for (const [key, entry] of [...dsPools]) {
   504→      if (key === dataSourceId || key.startsWith(prefix)) {
   505→        dsPools.delete(key);
   506→        entry.pool.end().catch(() => undefined);
   507→      }
   508→    }
   509→  } else {
   510→    for (const [id, entry] of dsPools) {
   511→      dsPools.delete(id);
   512→      entry.pool.end().catch(() => undefined);
   513→    }
   514→  }
   515→}
   516→
   517→export interface ExecResult {
   518→  rows: Record<string, any>[];
   519→  rowCount: number;
   520→  /** true 表示结果被 MAX_ROWS 截断 */
   521→  truncated: boolean;
   522→  finalSql: string;
   523→  /** P1-3：true 表示 AST 解析失败放行（正则白名单兜底），供路由层审计 */
   524→  astFallback?: boolean;
   525→}
   526→
   527→export type ExecOutcome =
   528→  | { ok: true; result: ExecResult }
   529→  | { ok: false; reason: string; /** EXPLAIN 防线拦截（预估扫描量超阈值）：调用方可识别此标记做定向呈现，而非普通执行失败 */ guardBlocked?: boolean };
   530→
   531→// ---------- EXPLAIN 防线（P0：防大扫描拖垮业务库） ----------
   532→
   533→/** 防线阈值：预估扫描行数超过该值则拦截。环境变量 SQL_EXPLAIN_MAX_ROWS（默认 100 万；0=关闭防线） */
   534→export function explainGuardMaxRows(scenario: QueryScenario = 'interactive'): number {
   535→  const raw = Number(process.env.SQL_EXPLAIN_MAX_ROWS);
   536→  const base = Number.isFinite(raw) && raw >= 0 ? Math.floor(raw) : 1_000_000;
   537→  if (base === 0) return 0;
   538→  // 后台导出/报告任务天然倾向大范围聚合，阈值放宽 10 倍（仍是防线，防的是"失控"而非"大"）
   539→  return scenario === 'export' ? base * 10 : base;
   540→}
   541→
   542→/** 递归遍历 EXPLAIN FORMAT=JSON 计划树，收集扫描行数估计（取最大值）。
   543→ *  兼容两代格式：MySQL 8.0 为 table 节点级 rows_examined_per_scan；MySQL 9.x 为节点级 estimated_rows */
   544→function mysqlJsonScanRows(node: unknown): number {
   545→  if (!node || typeof node !== 'object') return 0;
   546→  // 单次受控断言：上方守卫已排除 null/标量，EXPLAIN JSON 为驱动返回的动态结构
   547→  const obj = node as Record<string, unknown>;
   548→  let max = 0;
   549→  const examined = Number(obj.rows_examined_per_scan);
   550→  if (Number.isFinite(examined) && examined > max) max = examined;
   551→  const estimated = Number(obj.estimated_rows);
   552→  if (Number.isFinite(estimated) && estimated > max) max = estimated;
   553→  for (const v of Object.values(obj)) {
   554→    if (v && typeof v === 'object') {
   555→      const r = mysqlJsonScanRows(v);
   556→      if (r > max) max = r;
   557→    }
   558→  }
   559→  return max;
   560→}
   561→
   562→/** MySQL EXPLAIN 结果 → 预估扫描行数（取各表最大值）。兼容三种返回形态：
   563→ *  1. 传统表格（多列对象数组，rows 字段）2. FORMAT=JSON（单列 EXPLAIN，内为 JSON 文本）
   564→ *  3. 树形文本（MySQL 8.0.16+ 部分驱动/版本默认，单列 EXPLAIN，含 "rows=N" 标注） */
   565→export function parseMysqlExplainRows(explainRows: Record<string, unknown>[]): number {
   566→  const list = Array.isArray(explainRows) ? explainRows : [];
   567→  let max = 0;
   568→  // 形态 1：传统表格多列（含数值 rows 字段）
   569→  for (const r of list) {
   570→    const v = Number(r?.rows);
   571→    if (Number.isFinite(v) && v > max) max = v;
   572→  }
   573→  if (max > 0) return max;
   574→  // 形态 2/3：单列 EXPLAIN 文本（JSON 或树形）
   575→  const text = list.length > 0 ? list[0]?.EXPLAIN : null;
   576→  if (typeof text !== 'string' || text.trim() === '') return max;
   577→  const trimmed = text.trim();
   578→  if (trimmed.startsWith('{')) {
   579→    try {
   580→      max = mysqlJsonScanRows(JSON.parse(trimmed));
   581→    } catch { /* 畸形 JSON 落到树形正则 */ }
   582→  }
   583→  if (max > 0) return max;
   584→  // 树形文本：提取所有 "rows=N" 标注取最大（如 "-> Table scan on clients (cost=6.25 rows=60)"）
   585→  const re = /rows=(\d+(?:\.\d+)?)/gi;
   586→  let m: RegExpExecArray | null;
   587→  while ((m = re.exec(trimmed)) !== null) {
   588→    const v = Number(m[1]);
   589→    if (Number.isFinite(v) && v > max) max = v;
   590→  }
   591→  return max;
   592→}
   593→
   594→/** 递归遍历 PG 计划树，取扫描节点的预估行数最大值（节点类型以 Scan 结尾，含 Seq/Index/Bitmap/Foreign 等） */
   595→function pgScanRows(node: unknown): number {
   596→  if (!node || typeof node !== 'object') return 0;
   597→  // 单次受控断言：上方守卫已排除 null/标量，PG 计划树为驱动返回的动态结构
   598→  const obj = node as Record<string, unknown>;
   599→  let max = 0;
   600→  const type = String(obj['Node Type'] || '');
   601→  if (/Scan$/i.test(type)) {
   602→    const v = Number(obj['Plan Rows']);
   603→    if (Number.isFinite(v) && v > max) max = v;
   604→  }
   605→  const plans = obj.Plans;
   606→  for (const child of Array.isArray(plans) ? plans : []) {
   607→    const v = pgScanRows(child);
   608→    if (v > max) max = v;
   609→  }
   610→  return max;
   611→}
   612→
   613→/** PG EXPLAIN (FORMAT JSON) 结果 → 预估扫描行数（扫描节点 Plan Rows 最大值） */
   614→export function parsePgExplainRows(explainRows: Record<string, unknown>[]): number {
   615→  const first = Array.isArray(explainRows) ? explainRows[0] : null;
   616→  const planWrapper = first && typeof first === 'object' ? first['QUERY PLAN'] : null;
   617→  const root = Array.isArray(planWrapper) ? planWrapper[0] : null;
   618→  // 单次受控断言：计划树节点为 PG 驱动返回的动态结构，typeof 守卫后仅取 Plan 字段
   619→  return pgScanRows(root && typeof root === 'object' ? (root as Record<string, unknown>).Plan : null);
   620→}
   621→
   622→/**
   623→ * EXPLAIN 防线：校验/行过滤注入通过后、真执行前，先 EXPLAIN 评估扫描量。
   624→ * - 超阈值：返回拦截原因（带 guardBlocked 标记），不执行
   625→ * - EXPLAIN 自身失败：fail-open 放行（防线尽力而为，不因权限/方言差异阻断正常查询），埋点 error
   626→ * 口径说明：MySQL rows=预计检查行数（准确）；PG Plan Rows=扫描节点预估输出行数（过滤后估计，
   627→ * 强过滤大表可能低估，但无过滤的大范围聚合——最主要的风险场景——能准确拦截）。
   628→ */
   629→async function explainGuard(
   630→  entry: DsPoolEntry,
   631→  finalSql: string,
   632→  scenario: QueryScenario
   633→): Promise<{ blocked: true; reason: string } | { blocked: false }> {
   634→  const maxRows = explainGuardMaxRows(scenario);
   635→  if (maxRows <= 0) return { blocked: false };
   636→  try {
   637→    let estimated = 0;
   638→    if (entry.dialect === 'pg') {
   639→      const result = await entry.pool.query<Record<string, unknown>>(`EXPLAIN (FORMAT JSON) ${finalSql}`);
   640→      estimated = parsePgExplainRows(result.rows || []);
   641→    } else {
   642→      // FORMAT=JSON 跨版本结构稳定（8.0: rows_examined_per_scan / 9.x: estimated_rows），解析器两代兼容
   643→      const [rows] = await entry.pool.query<mysql.RowDataPacket[]>(`EXPLAIN FORMAT=JSON ${finalSql}`);
   644→      estimated = parseMysqlExplainRows(rows || []);
   645→    }
   646→    if (estimated > maxRows) {
   647→      observeExplainGuard('blocked', entry.dialect);
   648→      const fmt = (n: number) => (n >= 10000 ? `${(n / 10000).toFixed(1)} 万` : `${n}`);
   649→      return {
   650→        blocked: true,
   651→        reason: `EXPLAIN_GUARD: 该查询预估扫描约 ${fmt(estimated)} 行，超过安全阈值 ${fmt(maxRows)} 行，为保护数据源性能已拦截。请增加时间范围、部门或维度等筛选条件收窄查询范围后重试。`,
   652→      };
   653→    }
   654→    observeExplainGuard('passed', entry.dialect);
   655→    return { blocked: false };
   656→  } catch (err: any) {
   657→    // fail-open：EXPLAIN 失败（权限/方言特性等）不阻断正常执行
   658→    observeExplainGuard('error', entry.dialect);
   659→    logger.warn('[explain-guard] EXPLAIN 评估失败（放行执行）:', String(err?.message || err).slice(0, 120));
   660→    return { blocked: false };
   661→  }
   662→}
   663→
   664→/** data_sources 配置读取行（config_json 落库 JSON 文本） */
   665→interface DataSourceConfigRow extends mysql.RowDataPacket {
   666→  type: string;
   667→  config_json: string | null;
   668→}
   669→
   670→/** 读取数据源连接配置（含密码，仅服务端使用；dataVersion 指纹探测亦复用） */
   671→export async function loadDataSourceConfig(dataSourceId: string): Promise<{ type: string; config: any } | null> {
   672→  const [rows] = await getPool().query<DataSourceConfigRow[]>('SELECT type, config_json FROM data_sources WHERE id = ?', [dataSourceId]);
   673→  const ds = rows[0];
   674→  if (!ds) return null;
   675→  let config: Record<string, unknown> | string | null = ds.config_json;
   676→  if (typeof config === 'string') {
   677→    // 单次受控断言：config_json 为落库 JSON 文本，解析结果按配置对象口径使用（畸形 JSON 落 catch 回退空对象）
   678→    try { config = JSON.parse(config) as Record<string, unknown>; } catch { config = {}; }
   679→  }
   680→  config = config || {};
   681→  // P0：落库密码为 AES-256-GCM 密文，连接前解密（明文存量透传）
   682→  if (config.password) config.password = decryptSecret(String(config.password));
   683→  return { type: String(ds.type || ''), config };
   684→}
   685→
   686→export function getDsPool(dataSourceId: string, dialect: SqlDialect, config: any, scenario: QueryScenario = 'interactive'): DsPoolEntry {
   687→  const key = dsPoolKey(dataSourceId, scenario);
   688→  let entry = dsPools.get(key);
   689→  if (!entry) {
   690→    const poolMax = dsPoolScenarioMax(scenario);
   691→    const timeoutMs = scenarioTimeoutMs(scenario);
   692→    if (dialect === 'pg') {
   693→      // PostgreSQL / Greenplum：同属 PG 协议。超时由服务端 statement_timeout 按场景池强制，
   694→      // 连接级超时用 connectionTimeoutMillis；只读保障以 SELECT-only 校验 + 单语句为主防线。
   695→      entry = {
   696→        dialect: 'pg',
   697→        pool: new pg.Pool({
   698→          host: config?.host || '127.0.0.1',
   699→          port: Number(config?.port) || 5432,
   700→          user: config?.username || 'postgres',
   701→          password: config?.password || '',
   702→          database: config?.database || undefined,
   703→          max: poolMax,
   704→          connectionTimeoutMillis: CONNECT_TIMEOUT_MS,
   705→          statement_timeout: timeoutMs,
   706→        }),
   707→      };
   708→    } else {
   709→      entry = {
   710→        dialect: 'mysql',
   711→        pool: mysql.createPool({
   712→          host: config?.host || '127.0.0.1',
   713→          port: Number(config?.port) || 3306,
   714→          user: config?.username || 'root',
   715→          password: config?.password || '',
   716→          database: config?.database || undefined,
   717→          connectionLimit: poolMax,
   718→          connectTimeout: CONNECT_TIMEOUT_MS,
   719→          multipleStatements: false,
   720→        }),
   721→      };
   722→    }
   723→    dsPools.set(key, entry);
   724→  }
   725→  return entry;
   726→}
   727→
   728→/**
   729→ * 校验并执行 SQL。dataSourceId 必须是支持真实执行的数据源类型
   730→ * （mysql / postgresql / greenplum），否则返回 UNSUPPORTED_DS_TYPE（调用方走演示模式）。
   731→ * rowFilters：P1-3 行级权限（实际表名 → 谓词），白名单校验通过后 AST 强制注入。
   732→ */
   733→/** Prometheus 埋点包装：计时 + 成败 label，真实实现见 executeSafeSqlImpl */
   734→export async function executeSafeSql(
   735→  dataSourceId: string,
   736→  rawSql: unknown,
   737→  allowedTables: { name: string; columns?: { name: string }[] }[],
   738→  sensitiveColumns: string[] = [],
   739→  maxRows: number = MAX_ROWS,
   740→  rowFilters: Record<string, string> = {},
   741→  scenario: QueryScenario = 'interactive'
   742→): Promise<ExecOutcome> {
   743→  const t0 = Date.now();
   744→  try {
   745→    const out = await executeSafeSqlImpl(dataSourceId, rawSql, allowedTables, sensitiveColumns, maxRows, rowFilters, scenario);
   746→    observeSqlExec(Date.now() - t0, out.ok === true);
   747→    return out;
   748→  } catch (err) {
   749→    observeSqlExec(Date.now() - t0, false);
   750→    throw err;
   751→  }
   752→}
   753→
   754→async function executeSafeSqlImpl(
   755→  dataSourceId: string,
   756→  rawSql: unknown,
   757→  allowedTables: { name: string; columns?: { name: string }[] }[],
   758→  sensitiveColumns: string[] = [],
   759→  maxRows: number = MAX_ROWS,
   760→  rowFilters: Record<string, string> = {},
   761→  scenario: QueryScenario = 'interactive'
   762→): Promise<ExecOutcome> {
   763→  const ds = await loadDataSourceConfig(dataSourceId);
   764→  if (!ds) return { ok: false, reason: '数据源不存在' };
   765→  // 文件数据源（v0.9.34：csv/json/excel 上传落应用库 upl_* 物理表）：无独立连接池，
   766→  // 方言按 MySQL 校验（应用库即 MySQL），执行改道应用库
   767→  const fileTable = dialectOfDsType(ds.type) ? null : getFilePhysicalTable(ds.config);
   768→  const dialect = dialectOfDsType(ds.type) || (fileTable ? 'mysql' : null);
   769→  if (!dialect) {
   770→    return { ok: false, reason: 'UNSUPPORTED_DS_TYPE' };
   771→  }
   772→
   773→  const check = validateSelectSql(rawSql, allowedTables, sensitiveColumns, dialect, maxRows);
   774→  if (check.ok !== true) return { ok: false, reason: check.reason };
   775→
   776→  // P1-3 行级权限：校验通过后、执行前强制注入（注入失败 fail-closed）
   777→  const injected = injectRowFilters(check.sql, rowFilters, dialect);
   778→  if (injected.ok !== true) return { ok: false, reason: injected.reason };
   779→  const finalSql = injected.sql;
