   786→      const timeoutMs = scenarioTimeoutMs(scenario);
   787→      const execSql = injectMysqlMaxExecTime(finalSql, timeoutMs);
   788→      const [fileRows] = await getPool().query({ sql: execSql, timeout: timeoutMs });
   789→      const fileList = (Array.isArray(fileRows) ? fileRows : []) as Record<string, any>[];
   790→      return {
   791→        ok: true,
   792→        result: {
   793→          rows: fileList.slice(0, maxRows),
   794→          rowCount: fileList.length,
   795→          truncated: fileList.length > maxRows,
   796→          finalSql,
   797→          astFallback: check.astFallback === true,
   798→        },
   799→      };
   800→    }
   801→    const entry = getDsPool(dataSourceId, dialect, ds.config, scenario);
   802→    const timeoutMs = scenarioTimeoutMs(scenario);
   803→    // EXPLAIN 防线：真执行前预估扫描量，超阈值拦截（大扫描防拖垮业务库；EXPLAIN 失败 fail-open）
   804→    const guard = await explainGuard(entry, finalSql, scenario);
   805→    if (guard.blocked) return { ok: false, reason: guard.reason, guardBlocked: true };
   806→    let list: Record<string, any>[];
   807→    if (entry.dialect === 'pg') {
   808→      // pg 驱动：超时由建池时的场景化 statement_timeout 承担，结果在 result.rows
   809→      const result = await entry.pool.query(finalSql);
   810→      list = Array.isArray(result.rows) ? result.rows : [];
   811→    } else {
   812→      // MySQL：驱动 query timeout + 服务端 MAX_EXECUTION_TIME hint 双保险（hint 仅注入执行串，
   813→      // 不改变返回给调用方的 finalSql，审计/展示口径保持业务 SQL 原貌）
   814→      const execSql = injectMysqlMaxExecTime(finalSql, timeoutMs);
   815→      const [rows] = await entry.pool.query({ sql: execSql, timeout: timeoutMs });
   816→      list = (Array.isArray(rows) ? rows : []) as Record<string, any>[];
   817→    }
   818→    return {
   819→      ok: true,
   820→      result: {
   821→        rows: list.slice(0, maxRows),
   822→        rowCount: list.length,
   823→        truncated: list.length > maxRows,
   824→        finalSql,
   825→        astFallback: check.astFallback === true,
   826→      },
   827→    };
   828→  } catch (err: any) {
   829→    return { ok: false, reason: `SQL 执行失败：${String(err?.message || err).slice(0, 200)}` };
   830→  }
   831→}
