   110→    if (k.startsWith(`${dataSourceId}::`)) cache.delete(k);
   111→  }
   112→  for (const k of semanticIndex.keys()) {
   113→    if (k.startsWith(`${dataSourceId}::`)) semanticIndex.delete(k);
   114→  }
   115→}
