   136→
   137→export interface SemanticIndexEntry {
   138→  /** L1 缓存键（命中后再校验 L1 条目仍存在，防索引残留误命中） */
   139→  key: string;
   140→  /** 原始问题（前端标注「来自相似问题缓存」用） */
   141→  question: string;
   142→  /** 归一化问题的 embedding（4 位小数存储，压缩 Redis 体积） */
   143→  vec: number[];
   144→  at: number;
   145→}
   146→
   147→/** 内存模式语义索引：idxKey = `${dataSourceId}::${variant}` */
   148→const semanticIndex = new Map<string, SemanticIndexEntry[]>();
