   150→function semanticIndexKey(dataSourceId: string, variant: string): string {
   151→  return `${dataSourceId}::${variant}`;
   152→}
   153→
   154→/** 简易余弦相似度；维度不一致返回 0 */
   155→function cosineSim(a: number[], b: number[]): number {
   156→  if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length || a.length === 0) return 0;
   157→  let dot = 0;
   158→  let na = 0;
   159→  let nb = 0;
   160→  for (let i = 0; i < a.length; i++) {
   161→    dot += a[i] * b[i];
   162→    na += a[i] * a[i];
   163→    nb += b[i] * b[i];
   164→  }
   165→  if (na === 0 || nb === 0) return 0;
   166→  return dot / (Math.sqrt(na) * Math.sqrt(nb));
   167→}
   168→
   169→/** 问题 embedding（基于归一化文本，标点/大小写差异不产生额外向量）；不可用返回 null */
