   172→  if (norm.length < SEMANTIC_MIN_QUESTION_LEN) return null;
   173→  try {
   174→    const vec = await callEmbedding(norm, 'query');
   175→    return Array.isArray(vec) && vec.length > 0 ? vec : null;
