   183→  const now = Date.now();
   184→  const alive = (list: SemanticIndexEntry[]) =>
   185→    list.filter((e) => e && typeof e.key === 'string' && Array.isArray(e.vec) && now - Number(e.at || 0) <= cacheTtlMs());
   186→  if (isRedisEnabled()) {
   187→    try {
   188→      const raw = await getStateStore().get(`qcidx:${idxKey}`);
   189→      if (!raw) return [];
   190→      const parsed = JSON.parse(raw);
   191→      return Array.isArray(parsed) ? alive(parsed) : [];
   192→    } catch {
   193→      return [];
   194→    }
   195→  }
   196→  const list = semanticIndex.get(idxKey) || [];
   197→  const kept = alive(list);
   198→  if (kept.length !== list.length) semanticIndex.set(idxKey, kept);
