   202→/** 写入语义索引（读-改-写：缓存场景可接受竞态，最坏丢失一条索引；同 key 覆盖更新） */
   203→async function indexSemanticEntry(dataSourceId: string, variant: string, key: string, question: string): Promise<void> {
   204→  const vec = await embedQuestion(question);
   205→  if (!vec) return;
   206→  const idxKey = semanticIndexKey(dataSourceId, variant);
   207→  const entry: SemanticIndexEntry = {
   208→    key,
   209→    question: String(question).slice(0, 200),
   210→    vec: vec.map((v) => Math.round(v * 1e4) / 1e4),
   211→    at: Date.now(),
