    13→/** 余弦相似度（与 knowledgeBase 同实现；内联避免相互 import 形成循环依赖） */
    14→function cosine(a: number[], b: number[]): number {
    15→  if (a.length !== b.length || a.length === 0) return 0;
    16→  let dot = 0;
    17→  let na = 0;
    18→  let nb = 0;
    19→  for (let i = 0; i < a.length; i++) {
    20→    dot += a[i] * b[i];
    21→    na += a[i] * a[i];
    22→    nb += b[i] * b[i];
    23→  }
    24→  if (na === 0 || nb === 0) return 0;
    25→  return dot / (Math.sqrt(na) * Math.sqrt(nb));
