   160→ * 借鉴 DAIL-SQL 多维度打分：
   161→ * - 问题语义相似度（P1-3）：样例向量落库 + 问题侧单次 embed，余弦 × 8（同义不同词也能召回）；
   162→ *   embedding 不可用/向量缺失时自动降级纯词法，行为与旧版一致
   163→ * - 问题词法相似度：bigram 重合
   164→ * - SQL 结构相似度：样例 SQL 引用的表与当前问题 schema-linking 圈定表的重合数 × 3
   165→ * 相同归一化 SQL 只保留得分最高的一条；按 token 预算贪心取 top，返回结构化问答对，
   166→ * 由调用方以 user/assistant 消息对注入（Vanna few-shot 注入方式）。
   167→ */
   168→export async function loadFewShotExamples(
   169→  dataSourceId: string,
   170→  question: string,
   171→  relevantTables: string[] = []
   172→): Promise<FewShotExample[]> {
   173→  const [rows] = await getPool().query<RowDataPacket[]>(
   174→    `SELECT question, sql_text, source, embedding FROM sql_examples
   175→     WHERE data_source_id = ? AND sql_text <> ''
   176→     ORDER BY id DESC LIMIT 100`,
   177→    [dataSourceId]
   178→  );
   179→  const relevantSet = new Set(relevantTables.map((t) => String(t).toLowerCase()));
   180→
   181→  // P1-3：问题侧仅 embed 一次；失败降级 null（纯词法打分）
   182→  let qVec: number[] | null = null;
   183→  try {
   184→    qVec = await callEmbedding(question.slice(0, 500), 'query');
   185→  } catch {
   186→    qVec = null;
   187→  }
   188→
   189→  const scored = rows
   190→    .map((r) => {
   191→      const rawSql = String(r.sql_text);
   192→      let semantic = 0;
   193→      if (qVec && typeof r.embedding === 'string' && r.embedding) {
   194→        try {
   195→          const vec = JSON.parse(r.embedding);
   196→          if (Array.isArray(vec)) semantic = cosine(qVec, vec as number[]) * 8;
   197→        } catch {
   198→          // 向量损坏时不加分，降级词法
   199→        }
   200→      }
   201→      const qScore = bigramOverlap(question, String(r.question)) + Math.max(0, semantic);
   202→      const sqlTables = extractTableRefs(stripCommentsAndStrings(rawSql));
   203→      const tableOverlap = relevantSet.size > 0 ? sqlTables.filter((t) => relevantSet.has(t)).length : 0;
   204→      return {
   205→        question: String(r.question),
   206→        sql: normalizeSql(rawSql),
   207→        source: (String(r.source) as FewShotExample['source']) || 'MANUAL',
   208→        score: qScore + tableOverlap * 3,
   209→      };
   210→    })
   211→    .filter((r) => r.score > 0);
   212→
   213→  // 相同 SQL 去重：保留最高分
   214→  const bySql = new Map<string, any>();
   215→  for (const s of scored) {
   216→    const prev = bySql.get(s.sql);
   217→    if (!prev || s.score > prev.score) bySql.set(s.sql, s);
   218→  }
   219→  const ranked = [...bySql.values()].sort((a, b) => b.score - a.score);
   220→
   221→  // token 预算内贪心取 top（最多 3 条）
   222→  const picked: FewShotExample[] = [];
   223→  let used = 0;
   224→  for (const ex of ranked) {
   225→    if (picked.length >= 3) break;
   226→    const cost = approxTokens(ex.question) + approxTokens(ex.sql);
   227→    if (used + cost > FEWSHOT_TOKEN_BUDGET) break;
   228→    used += cost;
   229→    picked.push({ question: ex.question, sql: ex.sql, source: ex.source });
   230→  }
   231→  return picked;
   232→}
