   447→          if (!ok) throw new Error('样例不存在或已被删除');
   448→        }
   449→        result.updatedCount++;
   450→        continue;
   451→      }
   452→      if (conflictId !== undefined) result.summary.conflictItems++; // append：同问题照常新建
   453→      else result.summary.newItems++;
   454→      if (!dryRun) {
   455→        const created = await createSqlExample({ dataSourceId, question, sql }, actor, 'IMPORT');
   456→        existingByQuestion.set(question, created.id);
   457→      } else {
   458→        existingByQuestion.set(question, -1);
   459→      }
   460→      result.importedCount++;
   461→    } catch (err: any) {
   462→      result.errorCount++;
   463→      result.errors.push({ question, message: err?.message || '未知错误' });
   464→    }
   465→  }
   466→
   467→  result.success = result.errorCount === 0;
   468→  return result;
   469→}
