     1→/**
     2→ * P2-5 SSE 会话韧性（企业级改进计划 2-5）：问数流式事件重放缓冲。
     3→ * 流式过程中客户端断网/断连时，服务端 LLM 链路仍继续执行并把事件写入本缓冲；
     4→ * 客户端凭 traceId + 已收事件序号（Last-Event-ID 语义）经专用端点续传，
     5→ * 已完成阶段即时回放、不重新执行 SQL。
     6→ *
     7→ * 单机进程内实现（local-accel）：多实例部署重连到不同实例时缓冲未命中，
     8→ * 端点返回 404 由前端降级为完整重试；部署指南建议网关开启粘性会话。
     9→ */
    10→export interface BufferedSseEvent {
    11→  /** 从 1 递增的事件序号（SSE id 字段） */
    12→  seq: number;
    13→  event: string;
    14→  data: string;
    15→}
    16→
    17→interface TraceBuffer {
    18→  userId: number;
    19→  events: BufferedSseEvent[];
    20→  /** 终态事件（done/clarify/refuse/error）的序号；0=进行中 */
    21→  terminalSeq: number;
    22→  /** 终态到达时间（TTL 清扫依据）；进行中为创建时间 */
    23→  touchedAt: number;
    24→  listeners: Set<(e: BufferedSseEvent) => void>;
    25→}
    26→
    27→/** 终态事件集合：到达后该 traceId 不再产生新事件 */
    28→const TERMINAL_EVENTS = new Set(['done', 'clarify', 'refuse', 'error']);
    29→/** 终态后保留 10 分钟供断线重连回放；进行中的缓冲最长保留 30 分钟（异常泄漏兜底） */
    30→const TERMINAL_TTL_MS = 10 * 60 * 1000;
    31→const PENDING_TTL_MS = 30 * 60 * 1000;
    32→/** 单 trace 事件上限（异常刷屏兜底，正常链路 <100 条） */
    33→const MAX_EVENTS_PER_TRACE = 500;
    34→
    35→const buffers = new Map<string, TraceBuffer>();
    36→
    37→export function clearSseReplayBuffersForTest(): void {
    38→  buffers.clear();
    39→}
    40→
    41→/** 追加事件并返回分配的序号；同一 traceId 的序号从 1 单调递增 */
    42→export function appendQueryEvent(traceId: string, userId: number, event: string, data: string): number {
    43→  let buf = buffers.get(traceId);
    44→  if (!buf) {
    45→    buf = { userId, events: [], terminalSeq: 0, touchedAt: Date.now(), listeners: new Set() };
    46→    buffers.set(traceId, buf);
    47→  }
    48→  // 终态后不再接受新事件（防御重复调用）
    49→  if (buf.terminalSeq > 0) return buf.terminalSeq;
    50→  const entry: BufferedSseEvent = { seq: buf.events.length + 1, event, data };
    51→  if (buf.events.length < MAX_EVENTS_PER_TRACE) {
    52→    buf.events.push(entry);
    53→  }
    54→  if (TERMINAL_EVENTS.has(event)) {
    55→    buf.terminalSeq = entry.seq;
    56→  }
    57→  buf.touchedAt = Date.now();
    58→  for (const listener of buf.listeners) {
    59→    try {
    60→      listener(entry);
    61→    } catch {
    62→      // 监听器异常不影响主链路
    63→    }
    64→  }
    65→  return entry.seq;
    66→}
    67→
    68→export interface ReplaySlice {
    69→  userId: number;
    70→  events: BufferedSseEvent[];
    71→  /** true 表示终态事件已在本切片（或之前）到达 */
    72→  terminal: boolean;
    73→}
    74→
    75→/** 读取 seq > afterSeq 的存量事件；未知 traceId 返回 null。terminal=true 表示终态已到达（回放完即可关闭） */
    76→export function getEventsAfter(traceId: string, afterSeq: number): ReplaySlice | null {
    77→  const buf = buffers.get(traceId);
    78→  if (!buf) return null;
    79→  return {
    80→    userId: buf.userId,
    81→    events: buf.events.filter((e) => e.seq > afterSeq),
    82→    terminal: buf.terminalSeq > 0,
    83→  };
    84→}
    85→
    86→/** 校验 traceId 归属（本人或 ADMIN 可续传） */
    87→export function getTraceOwner(traceId: string): number | null {
    88→  return buffers.get(traceId)?.userId ?? null;
    89→}
    90→
    91→/** 是否已到达终态 */
    92→export function isTerminal(traceId: string): boolean {
    93→  return (buffers.get(traceId)?.terminalSeq ?? 0) > 0;
    94→}
    95→
    96→/** 终态事件判定（done/clarify/refuse/error） */
    97→export function isTerminalEvent(event: string): boolean {
    98→  return TERMINAL_EVENTS.has(event);
    99→}
   100→
   101→/** 订阅增量事件（续传端点回放存量后挂接）；返回退订函数 */
   102→export function subscribeTrace(traceId: string, listener: (e: BufferedSseEvent) => void): () => void {
   103→  const buf = buffers.get(traceId);
   104→  if (!buf) return () => undefined;
   105→  buf.listeners.add(listener);
   106→  return () => {
   107→    buf.listeners.delete(listener);
   108→  };
   109→}
   110→
   111→/** 清扫过期缓冲（终态 10 分钟 / 进行中 30 分钟） */
   112→export function sweepSseReplayBuffers(now = Date.now()): number {
   113→  let swept = 0;
   114→  for (const [traceId, buf] of buffers) {
   115→    const ttl = buf.terminalSeq > 0 ? TERMINAL_TTL_MS : PENDING_TTL_MS;
   116→    if (now - buf.touchedAt > ttl) {
   117→      buffers.delete(traceId);
   118→      swept++;
   119→    }
   120→  }
   121→  return swept;
   122→}
   123→
   124→let sweepTimer: ReturnType<typeof setInterval> | null = null;
   125→
   126→/** 启动周期性清扫（服务启动时调用一次，unref 不阻塞退出） */
   127→export function startSseReplaySweeper(): void {
   128→  if (sweepTimer) return;
   129→  sweepTimer = setInterval(() => sweepSseReplayBuffers(), 60 * 1000);
   130→  sweepTimer.unref?.();
   131→}
