    46→  return `tr_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`;
    47→}
    48→
    49→function clip(text: string | undefined, max: number): string {
    50→  if (typeof text !== 'string') return '';
    51→  const t = text.trim();
    52→  return t.length > max ? `${t.slice(0, max)}…` : t;
    53→}
    54→
    55→/** 旁路写入一步推导记录；调用方不必 await，失败仅打日志不阻断主链路 */
    56→export function recordTraceStep(traceId: string, meta: TraceMeta, step: TraceStep): Promise<void> {
    57→  let pool;
    58→  try {
    59→    pool = getPool();
    60→  } catch {
    61→    return Promise.resolve(); // DB 未初始化（如纯单测环境）静默跳过
    62→  }
    63→  return pool
