    66→        (trace_id, user_id, username, data_source_id, question, step_type, title, input_summary, output_summary, sql_text, row_count, duration_ms, status)
    67→       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    68→      [
    69→        traceId,
    70→        meta.userId,
    71→        meta.username,
    72→        meta.dataSourceId,
    73→        clip(meta.question, 500),
    74→        step.stepType,
    75→        clip(step.title, 100),
    76→        clip(step.inputSummary, 1000),
    77→        clip(step.outputSummary, 2000),
    78→        clip(step.sqlText, 2000),
    79→        typeof step.rowCount === 'number' ? step.rowCount : -1,
    80→        typeof step.durationMs === 'number' ? Math.round(step.durationMs) : 0,
    81→        step.status === 'fail' ? 'fail' : 'ok',
    82→      ]
    83→    )
    84→    .then(() => undefined)
