    96→export async function getTraceSteps(traceId: string): Promise<{ steps: TraceStepRow[]; ownerUserId: number | null }> {
    97→  const pool = getPool();
    98→  const [rows] = await pool.query<RowDataPacket[]>(
    99→    `SELECT step_type, title, input_summary, output_summary, sql_text, row_count, duration_ms, status, user_id, created_at
   100→     FROM query_trace WHERE trace_id = ? ORDER BY id ASC LIMIT 50`,
   101→    [traceId]
   102→  );
   103→  if (rows.length === 0) return { steps: [], ownerUserId: null };
   104→  const steps: TraceStepRow[] = rows.map((r, i) => ({
   105→    stepIndex: i + 1,
   106→    stepType: String(r.step_type) as TraceStepType,
   107→    title: String(r.title || ''),
   108→    inputSummary: String(r.input_summary || ''),
   109→    outputSummary: String(r.output_summary || ''),
   110→    sqlText: String(r.sql_text || ''),
   111→    rowCount: Number(r.row_count),
   112→    durationMs: Number(r.duration_ms),
   113→    status: r.status === 'fail' ? 'fail' : 'ok',
   114→    createdAt: String(r.created_at || ''),
   115→  }));
   116→  return { steps, ownerUserId: Number(rows[0].user_id) };
   117→}
