  schema: [],
  guidance: '',
  status: 'connected',
  dsType: 'mysql',
  sensitiveRemoved: [],
  allowIntrospection: false,
  rowFilters: {},
  dataSourceName: '测试数据源',
  fileBacked: false,
  ...over,
});

/** 归一化结果夹具（normalizeQueryResult 打桩返回值） */
const normalized = (over: Partial<NormalizedQueryResult> = {}): NormalizedQueryResult => ({
