  thoughtProcess: ['步骤'],
  aiExplanation: '解读',
  keyInsights: [],
  chartConfig: null,
  rows: [{ v: 1 }],
  columnNames: { v: '值' },
  columns: ['v'],
  totalCount: 1,
  kpiMetrics: [],
  suggestedQuestions: [],
